import triton
import triton.language as tl


@triton.jit
def _div_tensor_kernel(
    x, y, z, n_elements,
    D0: tl.constexpr, D1: tl.constexpr, D2: tl.constexpr, D3: tl.constexpr,
    D4: tl.constexpr, D5: tl.constexpr, D6: tl.constexpr, D7: tl.constexpr,
    XS0: tl.constexpr, XS1: tl.constexpr, XS2: tl.constexpr, XS3: tl.constexpr,
    XS4: tl.constexpr, XS5: tl.constexpr, XS6: tl.constexpr, XS7: tl.constexpr,
    YS0: tl.constexpr, YS1: tl.constexpr, YS2: tl.constexpr, YS3: tl.constexpr,
    YS4: tl.constexpr, YS5: tl.constexpr, YS6: tl.constexpr, YS7: tl.constexpr,
    ZS0: tl.constexpr, ZS1: tl.constexpr, ZS2: tl.constexpr, ZS3: tl.constexpr,
    ZS4: tl.constexpr, ZS5: tl.constexpr, ZS6: tl.constexpr, ZS7: tl.constexpr,
    MODE: tl.constexpr,
    PROMOTE: tl.constexpr,
    INT_ROUND: tl.constexpr,
    BLOCK_SIZE: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offs < n_elements

    rem = offs

    i7 = rem % D7
    rem = rem // D7
    i6 = rem % D6
    rem = rem // D6
    i5 = rem % D5
    rem = rem // D5
    i4 = rem % D4
    rem = rem // D4
    i3 = rem % D3
    rem = rem // D3
    i2 = rem % D2
    rem = rem // D2
    i1 = rem % D1
    rem = rem // D1
    i0 = rem % D0

    x_off = i0 * XS0 + i1 * XS1 + i2 * XS2 + i3 * XS3 + i4 * XS4 + i5 * XS5 + i6 * XS6 + i7 * XS7
    y_off = i0 * YS0 + i1 * YS1 + i2 * YS2 + i3 * YS3 + i4 * YS4 + i5 * YS5 + i6 * YS6 + i7 * YS7
    z_off = i0 * ZS0 + i1 * ZS1 + i2 * ZS2 + i3 * ZS3 + i4 * ZS4 + i5 * ZS5 + i6 * ZS6 + i7 * ZS7

    a = tl.load(x + x_off, mask=mask)
    b = tl.load(y + y_off, mask=mask)

    if INT_ROUND:
        q = a // b
        if MODE == 2:
            r = a - q * b
            adjust = (r != 0) & ((a < 0) != (b < 0))
            q = tl.where(adjust, q - 1, q)
    else:
        if PROMOTE == 1:
            a = a.to(tl.float32)
            b = b.to(tl.float32)
        elif PROMOTE == 2:
            a = a.to(tl.float64)
            b = b.to(tl.float64)

        q = a / b

        if MODE == 1:
            q = tl.where(q >= 0.0, tl.floor(q), -tl.floor(-q))
        elif MODE == 2:
            q = tl.floor(q)

    tl.store(z + z_off, q, mask=mask)


