    rem = rem // D5
    i4 = rem % D4
    rem = rem // D4
    i3 = rem % D3
    rem = rem // D3
    i2 = rem % D2
    rem = rem // D2
    i1 = rem % D1
    rem = rem // D1
    i0 = rem % D0

    x_off = i0 * XS0 + i1 * XS1 + i2 * XS2 + i3 * XS3 + i4 * XS4 + i5 * XS5 + i6 * XS6 + i7 * XS7
    z_off = i0 * ZS0 + i1 * ZS1 + i2 * ZS2 + i3 * ZS3 + i4 * ZS4 + i5 * ZS5 + i6 * ZS6 + i7 * ZS7

    a = tl.load(x + x_off, mask=mask)
    b = y

    if INT_ROUND:
        q = a // b
        if MODE == 2:
            r = a - q * b
            adjust = (r != 0) & ((a < 0) != (b < 0))
            q = tl.where(adjust, q - 1, q)
    else:
        if PROMOTE == 1:
            a = a.to(tl.float32)
