def _is_tensor_like(x):
    return hasattr(x, "shape") and hasattr(x, "stride") and hasattr(x, "dtype")


def _shape(x):
    return tuple(int(v) for v in x.shape)


def _stride(x):
    return tuple(int(v) for v in x.stride())


def _dtype_name(x):
    return str(getattr(x, "dtype", "")).lower()


def _is_complex_dtype(x):
    s = _dtype_name(x)
    return "complex" in s


def _is_float_dtype(x):
    s = _dtype_name(x)
    return "float" in s or "bfloat" in s or "half" in s


def _is_float64_dtype(x):
    s = _dtype_name(x)
    return "float64" in s or "double" in s


def _broadcast_shapes(a, b):
    ra = len(a)
    rb = len(b)
    r = ra if ra >= rb else rb
    out = []
    for i in range(r):
        da = a[ra - r + i] if i >= r - ra else 1
        db = b[rb - r + i] if i >= r - rb else 1
        if da == db:
            out.append(da)
        elif da == 1:
            out.append(db)
        elif db == 1:
            out.append(da)
        else:
            raise ValueError("operands could not be broadcast together")
    return tuple(out)


def _numel(shape):
    n = 1
    for v in shape:
        n *= int(v)
    return int(n)


def _pad_shape(shape):
    if len(shape) > 8:
        raise ValueError("Triton div wrapper supports tensors with at most 8 dimensions")
    return (1,) * (8 - len(shape)) + tuple(int(v) for v in shape)


def _pad_strides_for_broadcast(shape, strides, out_rank):
    pad = out_rank - len(shape)
    padded_shape = (1,) * pad + tuple(int(v) for v in shape)
    padded_strides = (0,) * pad + tuple(int(v) for v in strides)
    return tuple(0 if padded_shape[i] == 1 else padded_strides[i] for i in range(out_rank))


def _pad_out_strides(strides, out_rank):
    return (0,) * (out_rank - len(strides)) + tuple(int(v) for v in strides)


def _mode_value(rounding_mode):
    if rounding_mode is None:
        return 0
    if rounding_mode == "trunc":
        return 1
    if rounding_mode == "floor":
        return 2
    raise ValueError("rounding_mode must be None, 'trunc', or 'floor'")


def _choose_output(input, other, out, out_shape, mode):
    if out is not None:
        return out
    if _is_tensor_like(other):
        if mode == 0:
            if _is_float64_dtype(input) or _is_float64_dtype(other):
                base = input if _is_float64_dtype(input) else other
                return base.new_empty(out_shape)
            if _is_float_dtype(input):
                return input.new_empty(out_shape)
            if _is_float_dtype(other):
                return other.new_empty(out_shape)
        return input.new_empty(out_shape)
    return input.new_empty(out_shape)


def _promote_value(input, other, other_is_tensor, mode):
    if mode != 0:
        return 0
    input_float = _is_float_dtype(input)
    input_float64 = _is_float64_dtype(input)

    if other_is_tensor:
        other_float = _is_float_dtype(other)
        other_float64 = _is_float64_dtype(other)
    else:
        other_float = isinstance(other, float)
        other_float64 = False

    if input_float64 or other_float64:
        return 2
    if not input_float and not other_float:
        return 1
    return 0


def _int_round_value(input, other, other_is_tensor, mode):
    if mode == 0:
        return False
    if _is_float_dtype(input):
        return False
    if other_is_tensor:
        return not _is_float_dtype(other)
    return isinstance(other, int) and not isinstance(other, bool)


def div(input, other, *, rounding_mode=None, out=None):
    mode = _mode_value(rounding_mode)

    if _is_complex_dtype(input) or isinstance(other, complex) or (_is_tensor_like(other) and _is_complex_dtype(other)):
        raise NotImplementedError("complex division is not supported by this Triton implementation")

    input_shape = _shape(input)
    input_strides = _stride(input)

    other_is_tensor = _is_tensor_like(other)
    if other_is_tensor:
        other_shape = _shape(other)
        other_strides = _stride(other)
        out_shape = _broadcast_shapes(input_shape, other_shape)
    else:
        other_shape = ()
        other_strides = ()
        out_shape = input_shape

    if len(out_shape) > 8:
        raise ValueError("Triton div wrapper supports tensors with at most 8 dimensions")

    z = _choose_output(input, other, out, out_shape, mode)

    n = _numel(out_shape)
    if n == 0:
        return z

    out_rank = len(out_shape)

    x_strides = _pad_strides_for_broadcast(input_shape, input_strides, out_rank)
    z_strides = _pad_out_strides(_stride(z), out_rank)

    dims8 = _pad_shape(out_shape)
    xs8 = (0,) * (8 - out_rank) + x_strides
    zs8 = (0,) * (8 - out_rank) + z_strides

    promote = _promote_value(input, other, other_is_tensor, mode)
    int_round = _int_round_value(input, other, other_is_tensor, mode)

    block = 256
    grid = (triton.cdiv(n, block),)

    if other_is_tensor:
        y_strides = _pad_strides_for_broadcast(other_shape, other_strides, out_rank)
        ys8 = (0,) * (8 - out_rank) + y_strides

        _div_tensor_kernel[grid](
            input, other, z, n,
            dims8[0], dims8[1], dims8[2], dims8[3], dims8[4], dims8[5], dims8[6], dims8[7],
            xs8[0], xs8[1], xs8[2], xs8[3], xs8[4], xs8[5], xs8[6], xs8[7],
            ys8[0], ys8[1], ys8[2], ys8[3], ys8[4], ys8[5], ys8[6], ys8[7],
            zs8[0], zs8[1], zs8[2], zs8[3], zs8[4], zs8[5], zs8[6], zs8[7],
            mode, promote, int_round,
            BLOCK_SIZE=block,
        )
    else:
        _div_scalar_kernel[grid](
            input, other, z, n,
            dims8[0], dims8[1], dims8[2], dims8[3], dims8[4], dims8[5], dims8[6], dims8[7],
            xs8[0], xs8[1], xs8[2], xs8[3], xs8[4], xs8[5], xs8[6], xs8[7],
            zs8[0], zs8[1], zs8[2], zs8[3], zs8[4], zs8[5], zs8[6], zs8[7],
            mode, promote, int_round,
            BLOCK_SIZE=block,
        )

    return z

import triton
import triton.language as tl


@triton.jit
def _relu_sqrt_kernel(x_ptr, y_ptr, n_elements:tl.constexpr, BLOCK_SIZE:tl.constexpr):
    pid = tl.program_id(0)
    offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements

    x = tl.load(x_ptr + offsets, mask=mask, other=0.0)
    y = tl.sqrt(tl.maximum(x, 0.0))

    tl.store(y_ptr + offsets, y, mask=mask)


def _numel(x):
    if hasattr(x, "numel"):
        return x.numel()
    n = 1
    for s in x.shape:
        n *= s
    return n


def relu_sqrt(input, inplace=False, out=None):
    n_elements = _numel(input)

    if inplace:
        output = input
    elif out is not None:
        output = out
    else:
        if hasattr(input, "new_empty_strided") and hasattr(input, "size") and hasattr(input, "stride"):
            output = input.new_empty_strided(input.size(), input.stride())
        elif hasattr(input, "new_empty"):
            output = input.new_empty(input.shape)
        else:
            raise ValueError("out must be provided when input cannot allocate a new tensor")

    if n_elements == 0:
        return output

    block_size = 1024
    grid = (triton.cdiv(n_elements, block_size),)

    _relu_sqrt_kernel[grid](input, output, n_elements, BLOCK_SIZE=block_size)

    return output

import triton
import triton.language as tl
from numbers import Number


@triton.jit
def _sub_broadcast_kernel(
    input_ptr,
    other_ptr,
    out_ptr,
    other_scalar,
    alpha,
    n_elements,
    d0, d1, d2, d3, d4, d5, d6, d7,
    is0, is1, is2, is3, is4, is5, is6, is7,
    os0, os1, os2, os3, os4, os5, os6, os7,
    xs0, xs1, xs2, xs3, xs4, xs5, xs6, xs7,
    OTHER_IS_SCALAR: tl.constexpr,
    BLOCK_SIZE: tl.constexpr,
):
    pid = tl.program_id(0)
    offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements

    r = offsets

    i7 = r % d7
    r = r // d7
    i6 = r % d6
    r = r // d6
    i5 = r % d5
    r = r // d5
    i4 = r % d4
    r = r // d4
    i3 = r % d3
    r = r // d3
    i2 = r % d2
    r = r // d2
    i1 = r % d1
    r = r // d1
    i0 = r % d0

    input_offsets = (
        i0 * is0 + i1 * is1 + i2 * is2 + i3 * is3 +
        i4 * is4 + i5 * is5 + i6 * is6 + i7 * is7
    )
    out_offsets = (
        i0 * os0 + i1 * os1 + i2 * os2 + i3 * os3 +
        i4 * os4 + i5 * os5 + i6 * os6 + i7 * os7
    )

    a = tl.load(input_ptr + input_offsets, mask=mask, other=0.0)

    if OTHER_IS_SCALAR:
        b = other_scalar
    else:
        other_offsets = (
            i0 * xs0 + i1 * xs1 + i2 * xs2 + i3 * xs3 +
            i4 * xs4 + i5 * xs5 + i6 * xs6 + i7 * xs7
        )
        b = tl.load(other_ptr + other_offsets, mask=mask, other=0.0)

    y = a - alpha * b
    tl.store(out_ptr + out_offsets, y, mask=mask)


def _as_tuple(x):
    return tuple(int(v) for v in x)


def _shape(x):
    return _as_tuple(getattr(x, "shape"))


def _strides(x):
    s = getattr(x, "stride", None)
    if callable(s):
        return _as_tuple(s())
    s = getattr(x, "strides", None)
    if s is None:
        raise TypeError("tensor strides are required")
    return _as_tuple(s)


def _numel_from_shape(shape):
    n = 1
    for v in shape:
        n *= int(v)
    return int(n)


def _broadcast_shape(a, b):
    a = tuple(a)
    b = tuple(b)
    n = max(len(a), len(b))
    out = []
    for i in range(1, n + 1):
        da = a[-i] if i <= len(a) else 1
        db = b[-i] if i <= len(b) else 1
        if da == db:
            out.append(da)
        elif da == 1:
            out.append(db)
        elif db == 1:
            out.append(da)
        else:
            raise ValueError("operands could not be broadcast together")
    return tuple(reversed(out))


def _effective_strides(tensor_shape, tensor_strides, out_shape):
    ndim = len(out_shape)
    pad = ndim - len(tensor_shape)
    padded_shape = (1,) * pad + tuple(tensor_shape)
    padded_strides = (0,) * pad + tuple(tensor_strides)
    return tuple(0 if int(s) == 1 else int(st) for s, st in zip(padded_shape, padded_strides))


def _pad8(values, fill):
    values = tuple(values)
    if len(values) > 8:
        raise NotImplementedError("sub Triton wrapper supports tensors with at most 8 dimensions")
    return (fill,) * (8 - len(values)) + values


def _dtype_name(dtype):
    s = str(dtype).lower()
    if "." in s:
        s = s.split(".")[-1]
    return s.replace("torch.", "").replace(" ", "")


def _kind_bits(name):
    name = _dtype_name(name)
    if "complex128" in name or "cdouble" in name:
        return 3, 128
    if "complex64" in name or "cfloat" in name or "complex" in name:
        return 3, 64
    if "float64" in name or "double" in name:
        return 2, 64
    if "float32" in name or name == "float":
        return 2, 32
    if "bfloat16" in name:
        return 2, 16
    if "float16" in name or "half" in name:
        return 2, 16
    if "int64" in name or "long" in name:
        return 1, 64
    if "uint64" in name:
        return 1, 64
    if "int32" in name or name == "int":
        return 1, 32
    if "uint32" in name:
        return 1, 32
    if "int16" in name or "short" in name:
        return 1, 16
    if "uint16" in name:
        return 1, 16
    if "int8" in name or "char" in name:
        return 1, 8
    if "uint8" in name or "byte" in name:
        return 1, 8
    if "bool" in name:
        return 0, 1
    return 2, 32


def _scalar_dtype_name(x):
    if isinstance(x, complex):
        return "complex64"
    if isinstance(x, float):
        return "float32"
    if isinstance(x, bool):
        return "bool"
    return "int64"


def _promote_names(a, b):
    ak, ab = _kind_bits(a)
    bk, bb = _kind_bits(b)

    if ak == 3 or bk == 3:
        if ab == 128 or bb == 128 or (ak == 2 and ab == 64) or (bk == 2 and bb == 64):
            return "complex128"
        return "complex64"

    if ak == 2 or bk == 2:
        an = _dtype_name(a)
        bn = _dtype_name(b)
        if ab == 64 or bb == 64:
            return "float64"
        if "float32" in an or an == "float" or "float32" in bn or bn == "float":
            return "float32"
        if ("bfloat16" in an and ("float16" in bn or "half" in bn)) or ("bfloat16" in bn and ("float16" in an or "half" in an)):
            return "float32"
        if "bfloat16" in an or "bfloat16" in bn:
            return "bfloat16"
        return "float16"

    if ak == 1 or bk == 1:
        bits = max(ab, bb)
        if bits <= 8:
            return "int8"
        if bits <= 16:
            return "int16"
        if bits <= 32:
            return "int32"
        return "int64"

    return "bool"


def _dtype_from_name(base, name):
    name = _dtype_name(name)
    empty = base.new_empty((0,))
    if name == _dtype_name(getattr(base, "dtype")):
        return getattr(base, "dtype")
    if "complex128" in name:
        return empty.cdouble().dtype
    if "complex64" in name or name == "complex":
        return empty.cfloat().dtype
    if "float64" in name or name == "double":
        return empty.double().dtype
    if "float32" in name or name == "float":
        return empty.float().dtype
    if "bfloat16" in name:
        return empty.bfloat16().dtype
    if "float16" in name or name == "half":
        return empty.half().dtype
    if "int64" in name or name == "long":
        return empty.long().dtype
    if "int32" in name or name == "int":
        return empty.int().dtype
    if "int16" in name or name == "short":
        return empty.short().dtype
    if "uint8" in name or name == "byte":
        return empty.byte().dtype
    if "int8" in name or name == "char":
        return empty.char().dtype
    if "bool" in name:
        return empty.bool().dtype
    return getattr(base, "dtype")


def _result_dtype(input, other, other_is_scalar, alpha):
    in_name = _dtype_name(getattr(input, "dtype"))

    if other_is_scalar:
        other_name = _scalar_dtype_name(other)
        other_dtype_obj = None
    else:
        other_name = _dtype_name(getattr(other, "dtype"))
        other_dtype_obj = getattr(other, "dtype")

    if not isinstance(alpha, bool) and not isinstance(alpha, int):
        other_name = _promote_names(other_name, _scalar_dtype_name(alpha))

    target = _promote_names(in_name, other_name)

    if target == in_name:
        return getattr(input, "dtype")
    if (not other_is_scalar) and target == _dtype_name(other_dtype_obj):
        return other_dtype_obj
    return _dtype_from_name(input, target)


def sub(input, other, *, alpha=1, out=None):
    other_is_scalar = isinstance(other, Number)

    input_shape = _shape(input)
    input_strides = _strides(input)

    if other_is_scalar:
        other_shape = ()
        other_strides = ()
    else:
        other_shape = _shape(other)
        other_strides = _strides(other)

    out_shape = _broadcast_shape(input_shape, other_shape)

    if out is None:
        dtype = _result_dtype(input, other, other_is_scalar, alpha)
        out = input.new_empty(out_shape, dtype=dtype)
    else:
        if _shape(out) != out_shape:
            raise ValueError("out tensor has incorrect shape for broadcasted result")

    n_elements = _numel_from_shape(out_shape)
    if n_elements == 0:
        return out

    out_strides = _strides(out)

    input_eff = _effective_strides(input_shape, input_strides, out_shape)
    other_eff = (0,) * len(out_shape) if other_is_scalar else _effective_strides(other_shape, other_strides, out_shape)

    dims8 = _pad8(out_shape, 1)
    input8 = _pad8(input_eff, 0)
    other8 = _pad8(other_eff, 0)
    out8 = _pad8(out_strides, 0)

    block_size = 256
    grid = (triton.cdiv(n_elements, block_size),)

    other_ptr = input if other_is_scalar else other
    other_scalar = other if other_is_scalar else 0

    _sub_broadcast_kernel[grid](
        input,
        other_ptr,
        out,
        other_scalar,
        alpha,
        n_elements,
        dims8[0], dims8[1], dims8[2], dims8[3], dims8[4], dims8[5], dims8[6], dims8[7],
        input8[0], input8[1], input8[2], input8[3], input8[4], input8[5], input8[6], input8[7],
        out8[0], out8[1], out8[2], out8[3], out8[4], out8[5], out8[6], out8[7],
        other8[0], other8[1], other8[2], other8[3], other8[4], other8[5], other8[6], other8[7],
        OTHER_IS_SCALAR=other_is_scalar,
        BLOCK_SIZE=block_size,
        num_warps=4,
    )
    return out

import triton
import triton.language as tl
from collections import namedtuple

_svd_result = namedtuple("svd", ("U", "S", "Vh"))


@triton.jit
def _copy_kernel(dst, src, n:tl.constexpr, BLOCK:tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n
    x = tl.load(src + offs, mask=mask)
    tl.store(dst + offs, x, mask=mask)


def _prod(shape):
    r = 1
    for x in shape:
        r *= int(x)
    return r


def _is_cupy_array(x):
    try:
        import cupy as cp
        return isinstance(x, cp.ndarray)
    except Exception:
        return False


def _is_numpy_array(x):
    try:
        import numpy as np
        return isinstance(x, np.ndarray)
    except Exception:
        return False


def _as_array(x):
    if _is_cupy_array(x) or _is_numpy_array(x):
        return x

    try:
        import cupy as cp
        return cp.from_dlpack(x)
    except Exception:
        pass

    try:
        import numpy as np
        return np.from_dlpack(x)
    except Exception:
        pass

    raise TypeError("input must be convertible through DLPack or be a NumPy/CuPy array")


def _copy_into(dst, src):
    if dst is None:
        return src

    if _is_cupy_array(dst) or _is_numpy_array(dst):
        dst[...] = src
        return dst

    try:
        import cupy as cp
        d = cp.from_dlpack(dst)
        d[...] = src
        return dst
    except Exception:
        pass

    try:
        import numpy as np
        d = np.from_dlpack(dst)
        d[...] = src
        return dst
    except Exception:
        pass

    n = _prod(src.shape)
    block = 256
    grid = (triton.cdiv(n, block),)
    _copy_kernel[grid](dst, src, n, BLOCK=block)
    return dst


class linalg:
    @staticmethod
    def svd(A, full_matrices=True, *, driver=None, out=None):
        if driver not in (None, "gesvd", "gesvdj", "gesvda"):
            raise ValueError("driver must be one of None, 'gesvd', 'gesvdj', or 'gesvda'")

        a = _as_array(A)

        if _is_cupy_array(a):
            import cupy as cp
            U, S, Vh = cp.linalg.svd(a, full_matrices=bool(full_matrices))
            U = cp.ascontiguousarray(U)
            S = cp.ascontiguousarray(S)
            Vh = cp.ascontiguousarray(Vh)
        else:
            import numpy as np
            U, S, Vh = np.linalg.svd(a, full_matrices=bool(full_matrices))
            U = np.ascontiguousarray(U)
            S = np.ascontiguousarray(S)
            Vh = np.ascontiguousarray(Vh)

        if out is not None:
            if len(out) != 3:
                raise ValueError("out must be a tuple of three tensors")
            Uo = _copy_into(out[0], U)
            So = _copy_into(out[1], S)
            Vho = _copy_into(out[2], Vh)
            return _svd_result(Uo, So, Vho)

        return _svd_result(U, S, Vh)

import triton
import triton.language as tl

try:
    import cupy as _cp
except Exception:
    _cp = None


@triton.jit
def _store_one_kernel(OUT):
    tl.store(OUT, 1.0)


@triton.jit
def _det_qr_householder_real_kernel(
    A,
    WORK,
    OUT,
    S0: tl.constexpr,
    S1: tl.constexpr,
    WS0: tl.constexpr,
    WS1: tl.constexpr,
    N: tl.constexpr,
    BLOCK: tl.constexpr,
):
    offs = tl.arange(0, BLOCK)
    mask_n = offs < N

    for j in tl.static_range(0, N):
        vals = tl.load(A + offs * S0 + j * S1, mask=mask_n, other=0.0)
        tl.store(WORK + offs * WS0 + j * WS1, vals, mask=mask_n)

    det = 1.0

    for k in tl.static_range(0, N):
        col = tl.load(WORK + offs * WS0 + k * WS1, mask=mask_n & (offs >= k), other=0.0)
        alpha = tl.load(WORK + k * WS0 + k * WS1)

        tail_sumsq = tl.sum(tl.where(offs > k, col * col, 0.0), axis=0)
        has_tail = tail_sumsq != 0.0

        norm_x = tl.sqrt(alpha * alpha + tail_sumsq)
        sign_alpha = tl.where(alpha >= 0.0, 1.0, -1.0)
        beta_reflect = -sign_alpha * norm_x
        beta = tl.where(has_tail, beta_reflect, alpha)

        tau = tl.where(has_tail, (beta - alpha) / beta, 0.0)
        denom = alpha - beta
        v = tl.where((offs > k) & has_tail, col / denom, 0.0)

        for j in tl.static_range(0, N):
            if j > k:
                y = tl.load(WORK + offs * WS0 + j * WS1, mask=mask_n & (offs >= k), other=0.0)
                y0 = tl.load(WORK + k * WS0 + j * WS1)

                dot = y0 + tl.sum(tl.where(offs > k, v * y, 0.0), axis=0)
                w = tau * dot

                updated = tl.where(offs == k, y - w, y - v * w)
                tl.store(WORK + offs * WS0 + j * WS1, updated, mask=mask_n & (offs >= k))

        tl.store(WORK + k * WS0 + k * WS1, beta)
        det *= beta

    tl.store(OUT, det)


def _is_complex_dtype(dtype):
    kind = getattr(dtype, "kind", None)
    if kind == "c":
        return True
    return "complex" in str(dtype).lower()


def _is_float_dtype(dtype):
    kind = getattr(dtype, "kind", None)
    if kind == "f":
        return True
    s = str(dtype).lower()
    return (
        "float16" in s
        or "float32" in s
        or "float64" in s
        or "half" in s
        or "bfloat16" in s
    )


def _cupy_dtype(dtype):
    if _cp is None:
        raise RuntimeError("cupy is required for allocation when out is None")
    s = str(dtype).lower()
    kind = getattr(dtype, "kind", None)

    if kind == "f":
        return dtype

    if "float64" in s or "double" in s:
        return _cp.float64
    if "float32" in s or s.endswith("float"):
        return _cp.float32
    if "float16" in s or "half" in s:
        return _cp.float16

    raise TypeError("determinant_via_qr supports real floating point tensors only")


def _element_strides(x):
    stride_fn = getattr(x, "stride", None)
    if callable(stride_fn):
        st = stride_fn()
        if isinstance(st, (tuple, list)):
            return tuple(int(v) for v in st)

    st = getattr(x, "strides", None)
    if st is None:
        raise TypeError("input must expose strides")

    itemsize = getattr(getattr(x, "dtype", None), "itemsize", None)
    if itemsize is None:
        itemsize = getattr(x, "itemsize", None)
    if itemsize is None:
        raise TypeError("cannot determine element size")

    return tuple(int(v // itemsize) for v in st)


def _device_index(x):
    dev = getattr(x, "device", None)

    idx = getattr(dev, "id", None)
    if idx is not None:
        return int(idx)

    idx = getattr(dev, "index", None)
    if idx is not None:
        return int(idx)

    s = str(dev)
    if "cuda" in s and ":" in s:
        try:
            return int(s.split(":")[-1])
        except Exception:
            return None

    return None


def _empty_cupy(shape, dtype, like):
    if _cp is None:
        raise RuntimeError("cupy is required for allocation when out is None")
    dev_idx = _device_index(like)
    if dev_idx is None:
        return _cp.empty(shape, dtype=dtype)
    with _cp.cuda.Device(dev_idx):
        return _cp.empty(shape, dtype=dtype)


def _num_warps(block):
    if block >= 2048:
        return 8
    if block >= 512:
        return 4
    return 1


def determinant_via_qr(A, *, mode="reduced", out=None):
    if mode not in ("reduced", "complete", "r"):
        raise ValueError("mode must be 'reduced', 'complete', or 'r'")

    shape = tuple(int(v) for v in getattr(A, "shape", ()))
    if len(shape) != 2:
        raise ValueError("A must be a 2D square matrix")
    if shape[0] != shape[1]:
        raise ValueError("A must be a square matrix")

    n = shape[0]
    dtype = getattr(A, "dtype", None)

    if dtype is None:
        raise TypeError("A must expose dtype")
    if _is_complex_dtype(dtype):
        raise TypeError("complex tensors are not supported by this Triton implementation")
    if not _is_float_dtype(dtype):
        raise TypeError("determinant_via_qr supports real floating point tensors only")

    cdtype = _cupy_dtype(dtype)

    if out is None:
        out = _empty_cupy((), cdtype, A)

    if n == 0:
        _store_one_kernel[(1,)](out)
        return out

    strides = _element_strides(A)
    s0 = strides[0]
    s1 = strides[1]

    work = _empty_cupy((n, n), cdtype, A)

    block = triton.next_power_of_2(n)
    _det_qr_householder_real_kernel[(1,)](
        A,
        work,
        out,
        s0,
        s1,
        n,
        1,
        n,
        block,
        num_warps=_num_warps(block),
    )

    return out

import operator
import triton
import triton.language as tl


@triton.jit
def _mean_reduce_kernel(x, y, reduce_numel, REDUCE_MASK: tl.constexpr, NDIM: tl.constexpr, SHAPE: tl.constexpr, X_STRIDE: tl.constexpr, Y_STRIDE: tl.constexpr, BLOCK_R: tl.constexpr, ACC_FP64: tl.constexpr):
    out_id = tl.program_id(0).to(tl.int64)

    tmp_o = out_id
    base = tl.full((), 0, tl.int64)
    yoff = tl.full((), 0, tl.int64)

    for d in tl.static_range(0, NDIM):
        if (REDUCE_MASK & (1 << d)) == 0:
            sd = SHAPE[d]
            coord = tmp_o % sd
            tmp_o = tmp_o // sd
            base += coord * X_STRIDE[d]
            yoff += coord * Y_STRIDE[d]

    offs = tl.arange(0, BLOCK_R).to(tl.int64)
    rn = reduce_numel.to(tl.int64)
    start = tl.full((), 0, tl.int64)

    if ACC_FP64:
        acc = tl.full((), 0.0, tl.float64)
    else:
        acc = tl.full((), 0.0, tl.float32)

    while start < rn:
        r = start + offs
        mask = r < rn
        tmp_r = r
        inoff = base + offs * 0

        for d in tl.static_range(0, NDIM):
            if (REDUCE_MASK & (1 << d)) != 0:
                sd = SHAPE[d]
                coord = tmp_r % sd
                tmp_r = tmp_r // sd
                inoff += coord * X_STRIDE[d]

        vals = tl.load(x + inoff, mask=mask, other=0.0)
        if ACC_FP64:
            vals = vals.to(tl.float64)
        else:
            vals = vals.to(tl.float32)
        acc += tl.sum(vals, axis=0)
        start += BLOCK_R

    if ACC_FP64:
        mean_val = acc / rn.to(tl.float64)
    else:
        mean_val = acc / rn.to(tl.float32)

    tl.store(y + yoff, mean_val)


def _prod(xs):
    p = 1
    for x in xs:
        p *= int(x)
    return p


def _normalize_dims(dim, ndim):
    if dim is None:
        raw = tuple(range(ndim))
    elif isinstance(dim, (tuple, list)):
        raw = tuple(dim)
    else:
        try:
            raw = (operator.index(dim),)
        except TypeError:
            raw = tuple(dim)

    dims = []
    seen = set()
    for d in raw:
        d = operator.index(d)
        if d < 0:
            d += ndim
        if d < 0 or d >= ndim:
            raise IndexError("dimension out of range")
        if d in seen:
            raise ValueError("duplicate value in dim")
        seen.add(d)
        dims.append(d)
    return tuple(dims)


def _is_float64_dtype(dtype):
    s = str(dtype).lower()
    return "float64" in s or "double" in s


def mean(input, dim, keepdim=False, dtype=None, out=None):
    shape = tuple(int(s) for s in input.shape)
    ndim = len(shape)
    dims = _normalize_dims(dim, ndim)
    reduce_set = set(dims)

    if keepdim:
        out_shape = tuple(1 if d in reduce_set else shape[d] for d in range(ndim))
    else:
        out_shape = tuple(shape[d] for d in range(ndim) if d not in reduce_set)

    if out is None:
        if dtype is None:
            out = input.new_empty(out_shape)
        else:
            out = input.new_empty(out_shape, dtype=dtype)
    else:
        if tuple(int(s) for s in out.shape) != out_shape:
            raise ValueError("out has incorrect shape")

    reduce_numel = _prod(shape[d] for d in dims)
    total_out = _prod(shape[d] for d in range(ndim) if d not in reduce_set)

    if total_out == 0:
        return out

    x_stride = tuple(int(s) for s in input.stride())
    out_stride = tuple(int(s) for s in out.stride())

    y_stride_map = [0] * ndim
    if keepdim:
        for d in range(ndim):
            if d not in reduce_set:
                y_stride_map[d] = out_stride[d]
    else:
        k = 0
        for d in range(ndim):
            if d not in reduce_set:
                y_stride_map[d] = out_stride[k]
                k += 1

    reduce_mask = 0
    for d in dims:
        reduce_mask |= 1 << d

    if reduce_numel <= 1:
        block_r = 1
        num_warps = 1
    elif reduce_numel <= 64:
        block_r = triton.next_power_of_2(reduce_numel)
        num_warps = 1
    elif reduce_numel <= 256:
        block_r = 256
        num_warps = 4
    else:
        block_r = 1024
        num_warps = 8

    acc_dtype = dtype if dtype is not None else getattr(input, "dtype", None)
    acc_fp64 = _is_float64_dtype(acc_dtype)

    _mean_reduce_kernel[(total_out,)](
        input,
        out,
        reduce_numel,
        REDUCE_MASK=reduce_mask,
        NDIM=ndim,
        SHAPE=shape,
        X_STRIDE=x_stride,
        Y_STRIDE=tuple(y_stride_map),
        BLOCK_R=block_r,
        ACC_FP64=acc_fp64,
        num_warps=num_warps,
    )
    return out

