import operator
import triton
import triton.language as tl


@triton.jit
def _logsumexp_kernel(
    x_ptr,
    y_ptr,
    K: tl.constexpr,
    NDIM: tl.constexpr,
    SHAPE: tl.constexpr,
    X_STRIDES: tl.constexpr,
    Y_STRIDES_MAP: tl.constexpr,
    REDUCE: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)

    tmp = pid
    x_base = tl.full((), 0, tl.int64)
    y_off = tl.full((), 0, tl.int64)

    for rr in tl.static_range(0, NDIM):
        d = NDIM - 1 - rr
        if not REDUCE[d]:
            coord = tmp % SHAPE[d]
            tmp = tmp // SHAPE[d]
            x_base += coord * X_STRIDES[d]
            y_off += coord * Y_STRIDES_MAP[d]

    m = tl.full((), -float("inf"), tl.float32)
    s = tl.full((), 0.0, tl.float32)
    lane = tl.arange(0, BLOCK)

    for start in tl.range(0, K, BLOCK):
        r = start + lane
        r_tmp = r
        r_off = tl.zeros((BLOCK,), tl.int64)

        for rr in tl.static_range(0, NDIM):
            d = NDIM - 1 - rr
            if REDUCE[d]:
                coord = r_tmp % SHAPE[d]
                r_tmp = r_tmp // SHAPE[d]
                r_off += coord * X_STRIDES[d]

        vals = tl.load(x_ptr + x_base + r_off, mask=r < K, other=-float("inf")).to(tl.float32)
        b_m = tl.max(vals, axis=0)
        new_m = tl.maximum(m, b_m)

        contrib = tl.where(new_m == -float("inf"), 0.0, tl.exp(vals - new_m))
        b_s = tl.sum(contrib, axis=0)

        old_s = tl.where(new_m == -float("inf"), 0.0, s * tl.exp(m - new_m))
        s = old_s + b_s
        m = new_m

    res = m + tl.log(s)
    tl.store(y_ptr + y_off, res)


def _next_power_of_2(x):
    if x <= 1:
        return 1
    return 1 << (x - 1).bit_length()


def _prod(seq):
    p = 1
    for v in seq:
        p *= int(v)
    return p


def _canonical_dims(dim, ndim):
    try:
        dims = (operator.index(dim),)
    except TypeError:
        dims = tuple(operator.index(d) for d in dim)

    out = []
    seen = set()
    for d in dims:
        if d < 0:
            d += ndim
        if d < 0 or d >= ndim:
            raise IndexError("dimension out of range")
        if d in seen:
            raise RuntimeError("dim contains duplicate values")
        seen.add(d)
        out.append(d)
    return tuple(out)


def logsumexp(input, dim, keepdim=False, *, out=None):
    shape = tuple(int(s) for s in input.shape)
    ndim = len(shape)
    dims = _canonical_dims(dim, ndim)
    reduce_set = set(dims)

    if keepdim:
        out_shape = tuple(1 if d in reduce_set else shape[d] for d in range(ndim))
    else:
        out_shape = tuple(shape[d] for d in range(ndim) if d not in reduce_set)

    if out is None:
        out = input.new_empty(out_shape)
    else:
        if tuple(int(s) for s in out.shape) != out_shape:
            out.resize_(out_shape)

    total_out = 1
    K = 1
    reduce_flags = []
    for d, s in enumerate(shape):
        if d in reduce_set:
            K *= s
            reduce_flags.append(True)
        else:
            total_out *= s
            reduce_flags.append(False)

    if total_out == 0:
        return out

    x_strides = tuple(int(s) for s in input.stride())
    y_strides = tuple(int(s) for s in out.stride())

    y_strides_map = []
    out_i = 0
    for d in range(ndim):
        if d in reduce_set:
            y_strides_map.append(0)
        else:
            if keepdim:
                y_strides_map.append(y_strides[d])
            else:
                y_strides_map.append(y_strides[out_i])
                out_i += 1

    if K <= 0:
        block = 1
    else:
        block = min(_next_power_of_2(K), 1024)

    if block <= 64:
        num_warps = 1
    elif block <= 256:
        num_warps = 4
    else:
        num_warps = 8

    _logsumexp_kernel[(total_out,)](
        input,
        out,
        K,
        ndim,
        shape,
        x_strides,
        tuple(y_strides_map),
        tuple(reduce_flags),
        block,
        num_warps=num_warps,
    )

    return out

from __future__ import annotations

import triton
import triton.language as tl


@triton.jit
def _mul_relu_tensor_kernel(input_ptr, other_ptr, output_ptr, n_elements, BLOCK_SIZE: tl.constexpr):
    pid = tl.program_id(0)
    offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements

    x = tl.load(input_ptr + offsets, mask=mask, other=0.0)
    y = tl.load(other_ptr + offsets, mask=mask, other=0.0)

    z = x * y
    z = tl.where(z > 0, z, 0)

    tl.store(output_ptr + offsets, z, mask=mask)


@triton.jit
def _mul_relu_scalar_kernel(input_ptr, scalar, output_ptr, n_elements, BLOCK_SIZE: tl.constexpr):
    pid = tl.program_id(0)
    offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements

    x = tl.load(input_ptr + offsets, mask=mask, other=0.0)

    z = x * scalar
    z = tl.where(z > 0, z, 0)

    tl.store(output_ptr + offsets, z, mask=mask)


def _is_tensor_like(x):
    return hasattr(x, "data_ptr") or hasattr(x, "__cuda_array_interface__")


def _allocate_output(input, out, inplace):
    if inplace:
        return input
    if out is not None:
        return out
    if hasattr(input, "new_empty"):
        return input.new_empty(input.shape)
    if hasattr(input, "empty_like"):
        return input.empty_like()
    raise ValueError("out must be provided when input cannot allocate a new tensor")


def mul_relu(input, other, inplace=False, out=None) -> Tensor:
    output = _allocate_output(input, out, inplace)
    n_elements = input.numel()

    if n_elements == 0:
        return output

    block_size = 1024
    grid = (triton.cdiv(n_elements, block_size),)

    if _is_tensor_like(other):
        _mul_relu_tensor_kernel[grid](
            input,
            other,
            output,
            n_elements,
            BLOCK_SIZE=block_size,
        )
    else:
        _mul_relu_scalar_kernel[grid](
            input,
            other,
            output,
            n_elements,
            BLOCK_SIZE=block_size,
        )

    return output

