@triton.jit
def _asin_strided_kernel(
    input_ptr,
    output_ptr,
    n_elements,
    S0, S1, S2, S3, S4, S5, S6, S7, S8, S9, S10, S11, S12, S13, S14, S15,
    I0, I1, I2, I3, I4, I5, I6, I7, I8, I9, I10, I11, I12, I13, I14, I15,
    O0, O1, O2, O3, O4, O5, O6, O7, O8, O9, O10, O11, O12, O13, O14, O15,
    NDIM: tl.constexpr,
    BLOCK_SIZE: tl.constexpr,
):
    pid = tl.program_id(0)
    linear = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = linear < n_elements

    idx = linear
    in_offsets = tl.zeros((BLOCK_SIZE,), dtype=tl.int64)
    out_offsets = tl.zeros((BLOCK_SIZE,), dtype=tl.int64)

    if NDIM >= 16:
        d = idx % S15
        idx = idx // S15
        in_offsets += d * I15
        out_offsets += d * O15
    if NDIM >= 15:
        d = idx % S14
        idx = idx // S14
        in_offsets += d * I14
        out_offsets += d * O14
    if NDIM >= 14:
        d = idx % S13
        idx = idx // S13
        in_offsets += d * I13
        out_offsets += d * O13
    if NDIM >= 13:
        d = idx % S12
        idx = idx // S12
        in_offsets += d * I12
        out_offsets += d * O12
    if NDIM >= 12:
        d = idx % S11
        idx = idx // S11
        in_offsets += d * I11
        out_offsets += d * O11
    if NDIM >= 11:
        d = idx % S10
        idx = idx // S10
        in_offsets += d * I10
        out_offsets += d * O10
    if NDIM >= 10:
        d = idx % S9
        idx = idx // S9
        in_offsets += d * I9
        out_offsets += d * O9
    if NDIM >= 9:
        d = idx % S8
        idx = idx // S8
        in_offsets += d * I8
        out_offsets += d * O8
    if NDIM >= 8:
        d = idx % S7
        idx = idx // S7
        in_offsets += d * I7
        out_offsets += d * O7
    if NDIM >= 7:
        d = idx % S6
        idx = idx // S6
        in_offsets += d * I6
        out_offsets += d * O6
    if NDIM >= 6:
        d = idx % S5
        idx = idx // S5
        in_offsets += d * I5
        out_offsets += d * O5
    if NDIM >= 5:
        d = idx % S4
        idx = idx // S4
        in_offsets += d * I4
        out_offsets += d * O4
    if NDIM >= 4:
        d = idx % S3
        idx = idx // S3
        in_offsets += d * I3
        out_offsets += d * O3
    if NDIM >= 3:
        d = idx % S2
        idx = idx // S2
        in_offsets += d * I2
        out_offsets += d * O2
    if NDIM >= 2:
        d = idx % S1
        idx = idx // S1
        in_offsets += d * I1
        out_offsets += d * O1
    if NDIM >= 1:
        d = idx
        in_offsets += d * I0
        out_offsets += d * O0

    x = tl.load(input_ptr + in_offsets, mask=mask, other=0.0)
    y = tl.asin(x)
    tl.store(output_ptr + out_offsets, y, mask=mask)


def _shape_tuple(x):
    return tuple(int(s) for s in getattr(x, "shape"))


def _numel(shape):
    n = 1
    for s in shape:
        n *= int(s)
    return n


def _contiguous_strides(shape):
    strides = [1] * len(shape)
    acc = 1
    for i in range(len(shape) - 1, -1, -1):
        strides[i] = acc
        acc *= int(shape[i])
    return tuple(strides)


def _strides_tuple(x, shape):
    stride_fn = getattr(x, "stride", None)
    if callable(stride_fn):
        try:
            return tuple(int(s) for s in stride_fn())
        except TypeError:
            pass

    strides = getattr(x, "strides", None)
    if strides is None:
        return _contiguous_strides(shape)

    itemsize = getattr(x, "itemsize", None)
    if itemsize is None:
        dtype = getattr(x, "dtype", None)
        itemsize = getattr(dtype, "itemsize", 1)
    itemsize = int(itemsize) if itemsize is not None else 1

    return tuple(int(s) // itemsize for s in strides)


def _is_contiguous(shape, strides):
    expected = 1
    for size, stride in zip(reversed(shape), reversed(strides)):
        size = int(size)
        stride = int(stride)
        if size == 0:
            return True
        if size != 1:
            if stride != expected:
                return False
            expected *= size
    return True


def _pad(values, length, fill):
    values = tuple(int(v) for v in values)
    if len(values) >= length:
        return values[:length]
    return values + (fill,) * (length - len(values))


def _empty_like_input(x, shape):
    namespace_fn = getattr(x, "__array_namespace__", None)
    if callable(namespace_fn):
        xp = namespace_fn()
        dtype = getattr(x, "dtype", None)
        device = getattr(x, "device", None)
        try:
            return xp.empty(shape, dtype=dtype, device=device)
        except TypeError:
            try:
                return xp.empty(shape, dtype=dtype)
            except TypeError:
                pass

    new_empty = getattr(x, "new_empty", None)
    if callable(new_empty):
        return new_empty(shape)

    raise TypeError("out must be provided when an output tensor cannot be allocated from input")


def asin(input, *, out=None):
    shape = _shape_tuple(input)
    n_elements = _numel(shape)

    if out is None:
        out = _empty_like_input(input, shape)
    else:
        out_shape = _shape_tuple(out)
        if out_shape != shape:
            raise ValueError("out must have the same shape as input")

    if n_elements == 0:
        return out

    in_strides = _strides_tuple(input, shape)
    out_strides = _strides_tuple(out, shape)

    grid = (triton.cdiv(n_elements, _BLOCK_SIZE),)

    if _is_contiguous(shape, in_strides) and _is_contiguous(shape, out_strides):
        _asin_contiguous_kernel[grid](
            input,
            out,
            n_elements,
            BLOCK_SIZE=_BLOCK_SIZE,
            num_warps=4,
        )
        return out

    ndim = len(shape)
    if ndim > _MAX_DIMS:
        raise ValueError("non-contiguous tensors with more than 16 dimensions are not supported")

    params = (
        _pad(shape, _MAX_DIMS, 1)
        + _pad(in_strides, _MAX_DIMS, 0)
        + _pad(out_strides, _MAX_DIMS, 0)
    )

    _asin_strided_kernel[grid](
        input,
        out,
        n_elements,
        *params,
        NDIM=ndim,
        BLOCK_SIZE=_BLOCK_SIZE,
        num_warps=4,
    )

    return out

import triton
import triton.language as tl


@triton.jit
def _add_mean_kernel(
    input_ptr,
    other_ptr,
    out_ptr,
    other_scalar,
    alpha,
    N_OUT: tl.constexpr,
    N_RED: tl.constexpr,
    IN_STRIDES: tl.constexpr,
    OTHER_STRIDES: tl.constexpr,
    OUT_STRIDES: tl.constexpr,
    OUT_SHAPE: tl.constexpr,
    OUT_SUFFIX: tl.constexpr,
    OUT_FULL_DIMS: tl.constexpr,
    RED_DIMS: tl.constexpr,
    RED_SHAPE: tl.constexpr,
    RED_SUFFIX: tl.constexpr,
    OUT_NDIM: tl.constexpr,
    RED_NDIM: tl.constexpr,
    OTHER_IS_SCALAR: tl.constexpr,
    ACC_FLOAT64: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)

    base_in = tl.full((), 0, tl.int64)
    base_other = tl.full((), 0, tl.int64)
    base_out = tl.full((), 0, tl.int64)

    for oi in tl.static_range(0, OUT_NDIM):
        coord = (pid // OUT_SUFFIX[oi]) % OUT_SHAPE[oi]
        base_out += coord * OUT_STRIDES[oi]
        full_dim = OUT_FULL_DIMS[oi]
        if full_dim >= 0:
            base_in += coord * IN_STRIDES[full_dim]
            if not OTHER_IS_SCALAR:
                base_other += coord * OTHER_STRIDES[full_dim]

    if N_RED == 0:
        tl.store(out_ptr + base_out, float("nan"))
        return

    offsets = tl.arange(0, BLOCK)

    if ACC_FLOAT64:
        acc = tl.zeros((BLOCK,), dtype=tl.float64)
    else:
        acc = tl.zeros((BLOCK,), dtype=tl.float32)

    start = 0
    while start < N_RED:
        ridx = start + offsets
        mask = ridx < N_RED

        in_offsets = base_in + tl.zeros((BLOCK,), dtype=tl.int64)
        other_offsets = base_other + tl.zeros((BLOCK,), dtype=tl.int64)

        for ri in tl.static_range(0, RED_NDIM):
            rcoord = (ridx // RED_SUFFIX[ri]) % RED_SHAPE[ri]
            full_dim = RED_DIMS[ri]
            in_offsets += rcoord * IN_STRIDES[full_dim]
            if not OTHER_IS_SCALAR:
                other_offsets += rcoord * OTHER_STRIDES[full_dim]

        x = tl.load(input_ptr + in_offsets, mask=mask, other=0.0)

        if ACC_FLOAT64:
            x = x.to(tl.float64)
        else:
            x = x.to(tl.float32)

        if OTHER_IS_SCALAR:
            if ACC_FLOAT64:
                y = other_scalar + tl.zeros((BLOCK,), dtype=tl.float64)
            else:
                y = other_scalar + tl.zeros((BLOCK,), dtype=tl.float32)
        else:
            y = tl.load(other_ptr + other_offsets, mask=mask, other=0.0)
            if ACC_FLOAT64:
                y = y.to(tl.float64)
            else:
                y = y.to(tl.float32)

        val = x + y * alpha
        acc += tl.where(mask, val, 0.0)

        start += BLOCK

    total = tl.sum(acc, axis=0)
    mean = total / N_RED
    tl.store(out_ptr + base_out, mean)


def _is_number(x):
    return isinstance(x, (int, float, bool, complex))


def _shape(x):
    return tuple(int(v) for v in getattr(x, "shape", ()))


def _stride(x):
    s = getattr(x, "stride")
    if callable(s):
        s = s()
    return tuple(int(v) for v in s)


def _prod(xs):
    p = 1
    for x in xs:
        p *= int(x)
    return int(p)


def _suffix(shape):
    out = []
    p = 1
    for v in reversed(shape):
        out.append(p)
        p *= int(v)
    return tuple(reversed(out))


def _broadcast_shape(a, b):
    ra = len(a)
    rb = len(b)
    r = max(ra, rb)
    out = []
    for i in range(r):
        av = a[i - (r - ra)] if i >= r - ra else 1
        bv = b[i - (r - rb)] if i >= r - rb else 1
        if av == bv or av == 1 or bv == 1:
            out.append(max(av, bv))
        else:
            raise ValueError("input and other could not be broadcast together")
    return tuple(out)


def _expanded_strides(shape, strides, bshape):
    r = len(bshape)
    n = len(shape)
    out = []
    for i in range(r):
        si = i - (r - n)
        if si < 0:
            out.append(0)
        else:
            if int(shape[si]) == 1 and int(bshape[i]) != 1:
                out.append(0)
            else:
                out.append(int(strides[si]))
    return tuple(out)


def _normalize_dims(dim, ndim):
    if dim is None:
        return tuple(range(ndim))

    if isinstance(dim, int):
        dims = (dim,)
    else:
        dims = tuple(dim)

    out = []
    seen = set()
    for d in dims:
        d = int(d)
        if d < 0:
            d += ndim
        if d < 0 or d >= ndim:
            raise IndexError("dimension out of range")
        if d in seen:
            raise RuntimeError("dim appears multiple times")
        seen.add(d)
        out.append(d)
    return tuple(out)


def _dtype_rank(dtype):
    s = str(dtype).lower()
    if "complex128" in s:
        return 90
    if "complex64" in s or "complex" in s:
        return 80
    if "float64" in s or "double" in s:
        return 70
    if "float32" in s or "float" in s:
        return 60
    if "bfloat16" in s:
        return 50
    if "float16" in s or "half" in s:
        return 40
    if "int64" in s or "long" in s:
        return 30
    if "int32" in s or "int" in s:
        return 25
    if "int16" in s or "short" in s:
        return 20
    if "int8" in s or "char" in s or "bool" in s:
        return 10
    return 0


def _promoted_dtype(input, other, dtype):
    if dtype is not None:
        return dtype
    idt = getattr(input, "dtype", None)
    if _is_number(other):
        return idt
    odt = getattr(other, "dtype", None)
    if idt is None:
        return odt
    if odt is None:
        return idt
    return odt if _dtype_rank(odt) > _dtype_rank(idt) else idt


def _uses_float64(dtype):
    s = str(dtype).lower()
    return ("float64" in s) or ("double" in s) or ("complex128" in s)


def _ceil_power_of_2(x):
    if x <= 1:
        return 1
    return 1 << ((int(x) - 1).bit_length())


def add_mean(input, other, dim=None, alpha=1, keepdim=False, dtype=None, out=None):
    input_shape = _shape(input)
    input_strides = _stride(input)

    other_is_scalar = _is_number(other)
    if other_is_scalar:
        other_shape = ()
        other_strides_raw = ()
        other_ptr = input
        other_scalar = other
    else:
        other_shape = _shape(other)
        other_strides_raw = _stride(other)
        other_ptr = other
        other_scalar = 0.0

    bshape = _broadcast_shape(input_shape, other_shape)
    ndim = len(bshape)

    reduce_dims = _normalize_dims(dim, ndim)
    reduce_set = set(reduce_dims)

    if keepdim:
        out_shape = tuple(1 if i in reduce_set else bshape[i] for i in range(ndim))
        out_full_dims = tuple(-1 if i in reduce_set else i for i in range(ndim))
    else:
        out_shape = tuple(bshape[i] for i in range(ndim) if i not in reduce_set)
        out_full_dims = tuple(i for i in range(ndim) if i not in reduce_set)

    alloc_dtype = _promoted_dtype(input, other, dtype)

    if out is None:
        if alloc_dtype is not None:
            out = input.new_empty(out_shape, dtype=alloc_dtype)
        else:
            out = input.new_empty(out_shape)
    else:
        if tuple(int(v) for v in getattr(out, "shape", ())) != out_shape:
            raise ValueError("out has incorrect shape")

    n_out = _prod(out_shape)
    red_shape = tuple(bshape[i] for i in reduce_dims)
    n_red = _prod(red_shape)

    if n_out == 0:
        return out

    in_full_strides = _expanded_strides(input_shape, input_strides, bshape)

    if other_is_scalar:
        other_full_strides = tuple(0 for _ in range(ndim))
    else:
        other_full_strides = _expanded_strides(other_shape, other_strides_raw, bshape)

    out_strides = _stride(out)

    block = min(1024, _ceil_power_of_2(n_red if n_red > 0 else 1))
    num_warps = 1
    if block >= 2048:
        num_warps = 8
    elif block >= 512:
        num_warps = 4
    elif block >= 128:
        num_warps = 2

    acc_dtype = alloc_dtype if alloc_dtype is not None else getattr(out, "dtype", getattr(input, "dtype", None))
    acc_float64 = _uses_float64(acc_dtype)

    grid = (n_out,)

    _add_mean_kernel[grid](
        input,
        other_ptr,
        out,
        other_scalar,
        alpha,
        N_OUT=n_out,
        N_RED=n_red,
        IN_STRIDES=in_full_strides,
        OTHER_STRIDES=other_full_strides,
        OUT_STRIDES=out_strides,
        OUT_SHAPE=out_shape,
        OUT_SUFFIX=_suffix(out_shape),
        OUT_FULL_DIMS=out_full_dims,
        RED_DIMS=reduce_dims,
        RED_SHAPE=red_shape,
        RED_SUFFIX=_suffix(red_shape),
        OUT_NDIM=len(out_shape),
        RED_NDIM=len(reduce_dims),
        OTHER_IS_SCALAR=other_is_scalar,
        ACC_FLOAT64=acc_float64,
        BLOCK=block,
        num_warps=num_warps,
    )

    return out

import triton
import triton.language as tl


@triton.jit
def _sgd_update_kernel(
    P,
    G,
    B,
    N: tl.constexpr,
    LR,
    MOMENTUM,
    WEIGHT_DECAY,
    DAMPENING,
    MAXIMIZE: tl.constexpr,
    HAS_MOMENTUM: tl.constexpr,
    FIRST_MOMENTUM: tl.constexpr,
    NESTEROV: tl.constexpr,
    HAS_WEIGHT_DECAY: tl.constexpr,
    BLOCK: tl.constexpr,
):
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    mask = offs < N

    p = tl.load(P + offs, mask=mask, other=0.0).to(tl.float32)
    g = tl.load(G + offs, mask=mask, other=0.0).to(tl.float32)

    if MAXIMIZE:
        d = -g
    else:
        d = g

    if HAS_WEIGHT_DECAY:
        d = d + WEIGHT_DECAY * p

    if HAS_MOMENTUM:
        if FIRST_MOMENTUM:
            b = d
        else:
            old_b = tl.load(B + offs, mask=mask, other=0.0).to(tl.float32)
            b = MOMENTUM * old_b + (1.0 - DAMPENING) * d

        tl.store(B + offs, b, mask=mask)

        if NESTEROV:
            d = d + MOMENTUM * b
        else:
            d = b

    out = p - LR * d
    tl.store(P + offs, out, mask=mask)


@triton.jit
def _zero_kernel(X, N: tl.constexpr, BLOCK: tl.constexpr):
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    mask = offs < N
    z = tl.zeros((BLOCK,), tl.float32)
    tl.store(X + offs, z, mask=mask)


def _is_tensor_like(x):
    return hasattr(x, "data_ptr") or hasattr(x, "__cuda_array_interface__")


def _as_list(x):
    if x is None:
        return []
    if _is_tensor_like(x):
        return [x]
    if isinstance(x, (list, tuple)):
        return list(x)
    return list(x)


def _numel(x):
    if hasattr(x, "numel"):
        return int(x.numel())
    n = 1
    for s in x.shape:
        n *= int(s)
    return int(n)


def _get_grad(p):
    if isinstance(p, dict):
        if "grad" in p:
            return p["grad"]
        if "param" in p:
            return getattr(p["param"], "grad", None)
    return getattr(p, "grad", None)


def _get_param(p):
    if isinstance(p, dict) and "param" in p:
        return p["param"]
    return p


def _get_external_momentum_buffer(p):
    if isinstance(p, dict) and "momentum_buffer" in p:
        return p["momentum_buffer"]
    return None


def _validate_options(lr, momentum, weight_decay, dampening, nesterov):
    if lr < 0.0:
        raise ValueError("Invalid learning rate")
    if momentum < 0.0:
        raise ValueError("Invalid momentum")
    if weight_decay < 0.0:
        raise ValueError("Invalid weight_decay")
    if dampening < 0.0:
        raise ValueError("Invalid dampening")
    if nesterov and (momentum <= 0.0 or dampening != 0.0):
        raise ValueError("Nesterov momentum requires momentum > 0 and dampening == 0")


class _TritonSGD:
    def __init__(
        self,
        params,
        lr=1e-3,
        momentum=0,
        weight_decay=0,
        dampening=0,
        nesterov=False,
        maximize=False,
        foreach=None,
        differentiable=False,
        fused=None,
    ):
        _validate_options(float(lr), float(momentum), float(weight_decay), float(dampening), bool(nesterov))

        if differentiable:
            raise NotImplementedError("differentiable=True is not supported by this Triton SGD implementation")

        self.defaults = {
            "lr": float(lr),
            "momentum": float(momentum),
            "weight_decay": float(weight_decay),
            "dampening": float(dampening),
            "nesterov": bool(nesterov),
            "maximize": bool(maximize),
            "foreach": foreach,
            "differentiable": bool(differentiable),
            "fused": fused,
        }

        self.param_groups = []
        self.state = {}
        self._block = 1024

        if isinstance(params, dict):
            param_groups = [params]
        else:
            params_list = _as_list(params)
            if len(params_list) == 0:
                raise ValueError("optimizer got an empty parameter list")
            if isinstance(params_list[0], dict) and "params" in params_list[0]:
                param_groups = params_list
            else:
                param_groups = [{"params": params_list}]

        for group in param_groups:
            self.add_param_group(group)

    def add_param_group(self, group):
        if not isinstance(group, dict):
            raise TypeError("param group must be a dict")

        if "params" not in group:
            raise ValueError("param group must contain a 'params' entry")

        params = _as_list(group["params"])
        if len(params) == 0:
            raise ValueError("optimizer got an empty parameter group")

        new_group = dict(self.defaults)
        new_group.update(group)
        new_group["params"] = params

        _validate_options(
            float(new_group["lr"]),
            float(new_group["momentum"]),
            float(new_group["weight_decay"]),
            float(new_group["dampening"]),
            bool(new_group["nesterov"]),
        )

        self.param_groups.append(new_group)

    def zero_grad(self, set_to_none=True):
        for group in self.param_groups:
            for item in group["params"]:
                p = _get_param(item)
                g = _get_grad(item)
                if g is None:
                    continue
                if set_to_none and not isinstance(item, dict):
                    try:
                        setattr(p, "grad", None)
                        continue
                    except Exception:
                        pass
                n = _numel(g)
                if n == 0:
                    continue
                grid = (triton.cdiv(n, self._block),)
                _zero_kernel[grid](g, n, BLOCK=self._block, num_warps=4)

    def step(self, closure=None):
        loss = None
        if closure is not None:
            loss = closure()

        for group in self.param_groups:
            lr = float(group["lr"])
            momentum = float(group["momentum"])
            weight_decay = float(group["weight_decay"])
            dampening = float(group["dampening"])
            nesterov = bool(group["nesterov"])
            maximize = bool(group["maximize"])

            has_momentum = momentum != 0.0
            has_weight_decay = weight_decay != 0.0

            for item in group["params"]:
                p = _get_param(item)
                g = _get_grad(item)

                if p is None or g is None:
                    continue

                if bool(getattr(g, "is_sparse", False)):
                    raise NotImplementedError("Sparse gradients are not supported by this Triton SGD implementation")

                n = _numel(p)
                if n == 0:
                    continue

                buf = p
                first_momentum = False

                if has_momentum:
                    sid = id(p)
                    st = self.state.get(sid)
                    if st is None:
                        st = {}
                        self.state[sid] = st

                    ext_buf = _get_external_momentum_buffer(item)
                    if ext_buf is not None:
                        buf = ext_buf
                        st["momentum_buffer"] = buf
                    elif "momentum_buffer" in st:
                        buf = st["momentum_buffer"]
                    else:
                        if not hasattr(p, "new_empty"):
                            raise RuntimeError("Momentum requires tensor-like parameters supporting new_empty")
                        shape = getattr(p, "shape", (n,))
                        buf = p.new_empty(shape)
                        st["momentum_buffer"] = buf
                        first_momentum = True

                grid = (triton.cdiv(n, self._block),)
                _sgd_update_kernel[grid](
                    p,
                    g,
                    buf,
                    n,
                    lr,
                    momentum,
                    weight_decay,
                    dampening,
                    MAXIMIZE=maximize,
                    HAS_MOMENTUM=has_momentum,
                    FIRST_MOMENTUM=first_momentum,
                    NESTEROV=nesterov,
                    HAS_WEIGHT_DECAY=has_weight_decay,
                    BLOCK=self._block,
                    num_warps=4,
                )

        return loss

    def __call__(self, closure=None):
        return self.step(closure)

    def state_dict(self):
        return {
            "state": self.state,
            "param_groups": [
                {k: v for k, v in group.items() if k != "params"}
                for group in self.param_groups
            ],
        }

    def load_state_dict(self, state_dict):
        if "state" in state_dict:
            self.state = state_dict["state"]
        if "param_groups" in state_dict:
            saved_groups = state_dict["param_groups"]
            if len(saved_groups) != len(self.param_groups):
                raise ValueError("loaded state dict has a different number of parameter groups")
            for group, saved in zip(self.param_groups, saved_groups):
                params = group["params"]
                group.update(saved)
                group["params"] = params


def SGD(
    params,
    lr=1e-3,
    momentum=0,
    weight_decay=0,
    dampening=0,
    nesterov=False,
    maximize=False,
    foreach=None,
    differentiable=False,
    fused=None,
):
    return _TritonSGD(
        params,
        lr=lr,
        momentum=momentum,
        weight_decay=weight_decay,
        dampening=dampening,
        nesterov=nesterov,
        maximize=maximize,
        foreach=foreach,
        differentiable=differentiable,
        fused=fused,
    )

import math

import triton
import triton.language as tl


@triton.jit
def _matrix_power_eig_1x1_kernel(A, O, N:tl.constexpr, K:tl.constexpr, BLOCK:tl.constexpr):
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    mask = offs < N
    x = tl.load(A + offs, mask=mask, other=1.0).to(tl.float64)
    kk = tl.full((BLOCK,), K, tl.float64)
    y = tl.exp(kk * tl.log(x))
    tl.store(O + offs, y, mask=mask)


@triton.jit
def _matrix_power_eig_2x2_kernel(A, O, BATCH:tl.constexpr, K:tl.constexpr):
    pid = tl.program_id(0)
    base = pid * 4

    a = tl.load(A + base + 0).to(tl.float64)
    b = tl.load(A + base + 1).to(tl.float64)
    c = tl.load(A + base + 2).to(tl.float64)
    d = tl.load(A + base + 3).to(tl.float64)

    half_tr = (a + d) * 0.5
    half_diff = (a - d) * 0.5
    disc = half_diff * half_diff + b * c
    root = tl.sqrt(disc)

    l1 = half_tr + root
    l2 = half_tr - root
    kk = tl.full((), K, tl.float64)

    p1 = tl.exp(kk * tl.log(l1))
    p2 = tl.exp(kk * tl.log(l2))

    den = l1 - l2
    same = tl.abs(den) < 1.0e-12

    alpha = (p1 - p2) / den
    beta = (l1 * p2 - l2 * p1) / den

    alpha = tl.where(same, 0.0, alpha)
    beta = tl.where(same, p1, beta)

    o00 = alpha * a + beta
    o01 = alpha * b
    o10 = alpha * c
    o11 = alpha * d + beta

    tl.store(O + base + 0, o00)
    tl.store(O + base + 1, o01)
    tl.store(O + base + 2, o10)
    tl.store(O + base + 3, o11)


def _prod(xs):
    r = 1
    for x in xs:
        r *= int(x)
    return r


def _as_cupy_array(x, cp):
    if isinstance(x, cp.ndarray):
        return x
    try:
        return cp.from_dlpack(x)
    except Exception:
        return cp.fromDlpack(x.__dlpack__())


def _new_complex_output_like(A, shape, itemsize):
    if itemsize == 16:
        return A.cdouble().new_empty(tuple(shape))
    return A.cfloat().new_empty(tuple(shape))


def _cupy_matrix_power_eig(A, k, out):
    import cupy as cp

    ca = _as_cupy_array(A, cp)

    try:
        w, v = cp.linalg.eig(ca)
        vw = v * cp.power(w, k)[..., None, :]
        res = cp.matmul(vw, cp.linalg.inv(v))
    except Exception:
        n = int(ca.shape[-1])
        flat = ca.reshape((-1, n, n))
        first_w, first_v = cp.linalg.eig(flat[0])
        first_res = (first_v * cp.power(first_w, k)[None, :]) @ cp.linalg.inv(first_v)
        res_flat = cp.empty((int(flat.shape[0]), n, n), dtype=first_res.dtype)
        res_flat[0] = first_res
        for i in range(1, int(flat.shape[0])):
            wi, vi = cp.linalg.eig(flat[i])
            res_flat[i] = (vi * cp.power(wi, k)[None, :]) @ cp.linalg.inv(vi)
        res = res_flat.reshape(ca.shape)

    if out is not None:
        co = _as_cupy_array(out, cp)
        co[...] = res
        return out

    if isinstance(A, cp.ndarray):
        return res

    if hasattr(A, "new_empty"):
        if res.dtype.kind == "c":
            o = _new_complex_output_like(A, res.shape, res.dtype.itemsize)
        else:
            o = A.new_empty(tuple(res.shape))
        co = _as_cupy_array(o, cp)
        co[...] = res
        return o

    return res


def _triton_matrix_power_eig_fallback(A, k, out):
    if isinstance(k, complex):
        raise NotImplementedError("complex exponents require a backend eigensolver")

    shape = tuple(A.shape)
    if len(shape) < 2 or int(shape[-1]) != int(shape[-2]):
        raise ValueError("A must have shape (*, n, n)")

    n = int(shape[-1])
    if hasattr(A, "is_contiguous") and not A.is_contiguous():
        A_in = A.contiguous()
    else:
        A_in = A

    if out is None:
        O = A.new_empty(shape)
        O_kernel = O
    else:
        if hasattr(out, "is_contiguous") and not out.is_contiguous():
            O = out
            O_kernel = A.new_empty(shape)
        else:
            O = out
            O_kernel = out

    if n == 1:
        total = _prod(shape)
        block = 256
        grid = (triton.cdiv(total, block),)
        _matrix_power_eig_1x1_kernel[grid](A_in, O_kernel, total, float(k), BLOCK=block)
    elif n == 2:
        batch = _prod(shape[:-2])
        _matrix_power_eig_2x2_kernel[(batch,)](A_in, O_kernel, batch, float(k))
    else:
        raise NotImplementedError("Triton fallback supports only 1x1 and real-valued 2x2 matrices without an external eigensolver")

    if out is not None and O_kernel is not out:
        out.copy_(O_kernel)
        return out

    return O


def matrix_power_eig(A, k, *, out=None):
    try:
        return _cupy_matrix_power_eig(A, k, out)
    except Exception:
        return _triton_matrix_power_eig_fallback(A, k, out)

import triton
import triton.language as tl


@triton.jit
def _exp_contiguous_kernel(x_ptr, y_ptr, n_elements, input_is_float: tl.constexpr, BLOCK_SIZE: tl.constexpr):
    pid = tl.program_id(0)
    offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements

    if input_is_float:
        x = tl.load(x_ptr + offsets, mask=mask, other=0.0)
    else:
        x = tl.load(x_ptr + offsets, mask=mask, other=0).to(tl.float32)

    y = tl.exp(x)
    tl.store(y_ptr + offsets, y, mask=mask)


@triton.jit
def _exp_strided_kernel(
    x_ptr,
    y_ptr,
    n_elements,
    ndim: tl.constexpr,
    shape: tl.constexpr,
    x_strides: tl.constexpr,
    y_strides: tl.constexpr,
    input_is_float: tl.constexpr,
    BLOCK_SIZE: tl.constexpr,
):
    pid = tl.program_id(0)
    linear_offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = linear_offsets < n_elements

    remaining = linear_offsets
    x_offsets = tl.zeros((BLOCK_SIZE,), dtype=tl.int64)
    y_offsets = tl.zeros((BLOCK_SIZE,), dtype=tl.int64)

    for rev_axis in tl.static_range(0, ndim):
        axis = ndim - 1 - rev_axis
        idx = remaining % shape[axis]
        remaining = remaining // shape[axis]
        x_offsets += idx * x_strides[axis]
        y_offsets += idx * y_strides[axis]

    if input_is_float:
        x = tl.load(x_ptr + x_offsets, mask=mask, other=0.0)
    else:
        x = tl.load(x_ptr + x_offsets, mask=mask, other=0).to(tl.float32)

    y = tl.exp(x)
    tl.store(y_ptr + y_offsets, y, mask=mask)


def _shape(x):
    return tuple(int(v) for v in x.shape)


def _numel(x):
    n = getattr(x, "numel", None)
    if callable(n):
        return int(n())
    if n is not None:
        return int(n)
    s = getattr(x, "size", None)
    if isinstance(s, int):
        return int(s)
    total = 1
    for d in _shape(x):
        total *= d
    return int(total)


def _strides(x):
    stride = getattr(x, "stride", None)
    if callable(stride):
        return tuple(int(v) for v in stride())
    strides = getattr(x, "strides", None)
    itemsize = int(getattr(x, "itemsize", 1))
    return tuple(int(v) // itemsize for v in strides)


def _is_c_contiguous_from_strides(shape, strides):
    expected = 1
    for size, stride in zip(reversed(shape), reversed(strides)):
        if size == 0:
            return True
        if size != 1:
            if stride != expected:
                return False
            expected *= size
    return True


def _is_contiguous(x):
    is_contiguous = getattr(x, "is_contiguous", None)
    if callable(is_contiguous):
        return bool(is_contiguous())
    return _is_c_contiguous_from_strides(_shape(x), _strides(x))


def _dtype_keeps_output_dtype(dtype):
    s = str(dtype).lower()
    return ("float" in s) or ("complex" in s)


def _make_output(input):
    new_empty = getattr(input, "new_empty", None)
    if not callable(new_empty):
        raise TypeError("out must be provided when input does not support allocation")

    shape = _shape(input)
    dtype = getattr(input, "dtype", None)

    if dtype is None or _dtype_keeps_output_dtype(dtype):
        return new_empty(shape)

    scalar = new_empty(())
    float32_dtype = scalar.float().dtype
    return new_empty(shape, dtype=float32_dtype)


def exp(input, *, out=None):
    if out is None:
        out = _make_output(input)

    n_elements = _numel(input)
    if n_elements == 0:
        return out

    shape = _shape(input)
    input_is_float = _dtype_keeps_output_dtype(getattr(input, "dtype", ""))

    BLOCK_SIZE = 1024
    grid = (triton.cdiv(n_elements, BLOCK_SIZE),)

    if _is_contiguous(input) and _is_contiguous(out):
        _exp_contiguous_kernel[grid](
            input,
            out,
            n_elements,
            input_is_float,
            BLOCK_SIZE=BLOCK_SIZE,
            num_warps=4,
        )
    else:
        _exp_strided_kernel[grid](
            input,
            out,
            n_elements,
            len(shape),
            shape,
            _strides(input),
            _strides(out),
            input_is_float,
            BLOCK_SIZE=BLOCK_SIZE,
            num_warps=4,
        )

    return out

import triton
import triton.language as tl


@triton.jit
def _bitwise_and_tensor_kernel(
    input_ptr,
    other_ptr,
    out_ptr,
    n_elements,
    NDIM: tl.constexpr,
    SHAPE: tl.constexpr,
    LINEAR_STRIDES: tl.constexpr,
    INPUT_STRIDES: tl.constexpr,
    OTHER_STRIDES: tl.constexpr,
    OUT_STRIDES: tl.constexpr,
    BLOCK_SIZE: tl.constexpr,
):
    pid = tl.program_id(0)
    offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements

    input_offsets = tl.zeros((BLOCK_SIZE,), dtype=tl.int64)
    other_offsets = tl.zeros((BLOCK_SIZE,), dtype=tl.int64)
    out_offsets = tl.zeros((BLOCK_SIZE,), dtype=tl.int64)

    for dim in tl.static_range(0, NDIM):
        idx = (offsets // LINEAR_STRIDES[dim]) % SHAPE[dim]
        input_offsets += idx * INPUT_STRIDES[dim]
        other_offsets += idx * OTHER_STRIDES[dim]
        out_offsets += idx * OUT_STRIDES[dim]

    a = tl.load(input_ptr + input_offsets, mask=mask, other=0)
    b = tl.load(other_ptr + other_offsets, mask=mask, other=0)
    c = a & b
    tl.store(out_ptr + out_offsets, c, mask=mask)


@triton.jit
def _bitwise_and_scalar_kernel(
    input_ptr,
    other_value,
    out_ptr,
    n_elements,
    NDIM: tl.constexpr,
    SHAPE: tl.constexpr,
    LINEAR_STRIDES: tl.constexpr,
    INPUT_STRIDES: tl.constexpr,
    OUT_STRIDES: tl.constexpr,
    BLOCK_SIZE: tl.constexpr,
):
    pid = tl.program_id(0)
    offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements

    input_offsets = tl.zeros((BLOCK_SIZE,), dtype=tl.int64)
    out_offsets = tl.zeros((BLOCK_SIZE,), dtype=tl.int64)

    for dim in tl.static_range(0, NDIM):
        idx = (offsets // LINEAR_STRIDES[dim]) % SHAPE[dim]
        input_offsets += idx * INPUT_STRIDES[dim]
        out_offsets += idx * OUT_STRIDES[dim]

    a = tl.load(input_ptr + input_offsets, mask=mask, other=0)
    c = a & other_value
    tl.store(out_ptr + out_offsets, c, mask=mask)


def _is_tensor(x):
    return hasattr(x, "shape") and hasattr(x, "stride") and hasattr(x, "numel")


def _shape_tuple(x):
    return tuple(int(v) for v in x.shape)


def _stride_tuple(x):
    return tuple(int(v) for v in x.stride())


def _numel_from_shape(shape):
    n = 1
    for v in shape:
        n *= int(v)
    return int(n)


def _broadcast_shape(a_shape, b_shape):
    a_len = len(a_shape)
    b_len = len(b_shape)
    out = []
    n = a_len if a_len >= b_len else b_len

    for i in range(1, n + 1):
        a = a_shape[-i] if i <= a_len else 1
        b = b_shape[-i] if i <= b_len else 1

        if a == b:
            out.append(a)
        elif a == 1:
            out.append(b)
        elif b == 1:
            out.append(a)
        else:
            raise ValueError("input and other could not be broadcast together")

    out.reverse()
    return tuple(int(v) for v in out)


def _linear_strides(shape):
    strides = [1] * len(shape)
    acc = 1
    for i in range(len(shape) - 1, -1, -1):
        strides[i] = acc
        acc *= int(shape[i])
    return tuple(int(v) for v in strides)


def _aligned_broadcast_strides(shape, strides, out_shape):
    pad = len(out_shape) - len(shape)
    result = []

    for i in range(len(out_shape)):
        if i < pad:
            result.append(0)
        else:
            src_dim = i - pad
            if int(shape[src_dim]) == 1:
                result.append(0)
            else:
                result.append(int(strides[src_dim]))

    return tuple(result)


def _dtype_bits_and_signed(dtype):
    s = str(dtype)
    if s.endswith("bool"):
        return 0, False
    if "uint8" in s:
        return 8, False
    if "int8" in s:
        return 8, True
    if "uint16" in s:
        return 16, False
    if "int16" in s or "short" in s:
        return 16, True
    if "uint32" in s:
        return 32, False
    if "int32" in s or "int." in s:
        return 32, True
    if "uint64" in s:
        return 64, False
    if "int64" in s or "long" in s:
        return 64, True
    return 64, True


def _select_output_base(input, other):
    if not _is_tensor(other):
        return input

    if str(input.dtype) == str(other.dtype):
        return input

    ib, isigned = _dtype_bits_and_signed(input.dtype)
    ob, osigned = _dtype_bits_and_signed(other.dtype)

    if ib == 0 and ob != 0:
        return other
    if ob == 0 and ib != 0:
        return input

    if isigned == osigned:
        if ob > ib:
            return other
        return input

    if isigned and ib > ob:
        return input
    if osigned and ob > ib:
        return other

    if ib > ob:
        return input
    if ob > ib:
        return other

    return input if isigned else other


def _make_output(input, other, shape, out):
    if out is not None:
        if tuple(int(v) for v in out.shape) != shape:
            raise ValueError("out has incompatible shape")
        return out
    base = _select_output_base(input, other)
    return base.new_empty(shape)


def bitwise_and(input, other, *, out=None):
    input_shape = _shape_tuple(input)
    input_strides_raw = _stride_tuple(input)

    if _is_tensor(other):
        other_shape = _shape_tuple(other)
        other_strides_raw = _stride_tuple(other)
        out_shape = _broadcast_shape(input_shape, other_shape)
    else:
        other_shape = ()
        other_strides_raw = ()
        out_shape = input_shape

    output = _make_output(input, other, out_shape, out)

    n_elements = _numel_from_shape(out_shape)
    if n_elements == 0:
        return output

    ndim = len(out_shape)
    linear = _linear_strides(out_shape)
    input_strides = _aligned_broadcast_strides(input_shape, input_strides_raw, out_shape)
    out_strides = _aligned_broadcast_strides(_shape_tuple(output), _stride_tuple(output), out_shape)

    block_size = 1024
    grid = (triton.cdiv(n_elements, block_size),)

    if _is_tensor(other):
        other_strides = _aligned_broadcast_strides(other_shape, other_strides_raw, out_shape)
        _bitwise_and_tensor_kernel[grid](
            input,
            other,
            output,
            n_elements,
            NDIM=ndim,
            SHAPE=out_shape,
            LINEAR_STRIDES=linear,
            INPUT_STRIDES=input_strides,
            OTHER_STRIDES=other_strides,
            OUT_STRIDES=out_strides,
            BLOCK_SIZE=block_size,
            num_warps=4,
        )
    else:
        _bitwise_and_scalar_kernel[grid](
            input,
            other,
            output,
            n_elements,
            NDIM=ndim,
            SHAPE=out_shape,
            LINEAR_STRIDES=linear,
            INPUT_STRIDES=input_strides,
            OUT_STRIDES=out_strides,
            BLOCK_SIZE=block_size,
            num_warps=4,
        )

    return output

import triton
import triton.language as tl


@triton.jit
def _gelu_std_kernel(
    input_ptr,
    out_ptr,
    NDIM: tl.constexpr,
    SHAPE: tl.constexpr,
    IN_STRIDES: tl.constexpr,
    OUT_STRIDES: tl.constexpr,
    REDUCE_FLAGS: tl.constexpr,
    OUT_MAP: tl.constexpr,
    R: tl.constexpr,
    CORRECTION: tl.constexpr,
    APPROXIMATE: tl.constexpr,
    BLOCK_R: tl.constexpr,
):
    pid = tl.program_id(0)

    in_base = tl.full((), 0, tl.int64)
    out_offset = tl.full((), 0, tl.int64)
    tmp = pid

    for rd in tl.static_range(0, NDIM):
        d = NDIM - 1 - rd
        if not REDUCE_FLAGS[d]:
            coord = tmp % SHAPE[d]
            tmp = tmp // SHAPE[d]
            in_base += coord * IN_STRIDES[d]
            od = OUT_MAP[d]
            if od >= 0:
                out_offset += coord * OUT_STRIDES[od]

    if R == 0:
        tl.store(out_ptr + out_offset, tl.full((), float("nan"), tl.float32))
        return

    offs = tl.arange(0, BLOCK_R)
    acc_sum = tl.full((), 0.0, tl.float32)
    acc_sumsq = tl.full((), 0.0, tl.float32)

    for start in range(0, R, BLOCK_R):
        ridx = start + offs
        mask = ridx < R

        red_offset = tl.full((BLOCK_R,), 0, tl.int64)
        rtmp = ridx

        for rd in tl.static_range(0, NDIM):
            d = NDIM - 1 - rd
            if REDUCE_FLAGS[d]:
                rcoord = rtmp % SHAPE[d]
                rtmp = rtmp // SHAPE[d]
                red_offset += rcoord * IN_STRIDES[d]

        x = tl.load(input_ptr + in_base + red_offset, mask=mask, other=0.0).to(tl.float32)

        if APPROXIMATE == "tanh":
            x3 = x * x * x
            y = 0.5 * x * (1.0 + tl.tanh(0.7978845608028654 * (x + 0.044715 * x3)))
        else:
            y = 0.5 * x * (1.0 + tl.erf(x * 0.7071067811865476))

        y = tl.where(mask, y, 0.0)
        acc_sum += tl.sum(y, axis=0)
        acc_sumsq += tl.sum(y * y, axis=0)

    denom = R - CORRECTION
    if denom <= 0:
        result = tl.full((), float("nan"), tl.float32)
    else:
        mean_term = (acc_sum * acc_sum) / R
        var = (acc_sumsq - mean_term) / denom
        var = tl.maximum(var, 0.0)
        result = tl.sqrt(var)

    tl.store(out_ptr + out_offset, result)


def _prod(xs):
    p = 1
    for x in xs:
        p *= int(x)
    return p


def _normalize_dims(dim, ndim):
    if dim is None:
        return tuple(range(ndim))

    if isinstance(dim, int):
        dims = (dim,)
    else:
        dims = tuple(dim)

    normalized = []
    seen = set()
    for d in dims:
        d = int(d)
        if d < 0:
            d += ndim
        if d < 0 or d >= ndim:
            raise IndexError("dimension out of range")
        if d in seen:
            raise ValueError("duplicate value in dim")
        seen.add(d)
        normalized.append(d)

    return tuple(normalized)


def _make_output_shape(shape, reduce_dims, keepdim):
    reduce_set = set(reduce_dims)
    if keepdim:
        return tuple(1 if i in reduce_set else int(s) for i, s in enumerate(shape))
    return tuple(int(s) for i, s in enumerate(shape) if i not in reduce_set)


def _make_out_map(ndim, reduce_flags, keepdim):
    if keepdim:
        return tuple(i if not reduce_flags[i] else -1 for i in range(ndim))

    out_map = []
    j = 0
    for i in range(ndim):
        if reduce_flags[i]:
            out_map.append(-1)
        else:
            out_map.append(j)
            j += 1
    return tuple(out_map)


def _next_power_of_2(x):
    if x <= 1:
        return 1
    return 1 << (int(x) - 1).bit_length()


def gelu_std(input, dim=None, keepdim=False, correction=1, approximate="none", out=None):
    if approximate not in ("none", "tanh"):
        raise ValueError("approximate must be either 'none' or 'tanh'")

    shape = tuple(int(s) for s in input.shape)
    ndim = len(shape)

    reduce_dims = _normalize_dims(dim, ndim)
    reduce_set = set(reduce_dims)
    reduce_flags = tuple(i in reduce_set for i in range(ndim))

    out_shape = _make_output_shape(shape, reduce_dims, keepdim)

    if out is None:
        out = input.new_empty(out_shape)

    out_numel = _prod(out_shape)
    if out_numel == 0:
        return out

    r = 1
    for d in reduce_dims:
        r *= shape[d]

    in_strides = tuple(int(s) for s in input.stride())
    out_strides = tuple(int(s) for s in out.stride())
    out_map = _make_out_map(ndim, reduce_flags, keepdim)

    block_r = min(1024, _next_power_of_2(r if r > 0 else 1))
    num_warps = 1
    if block_r >= 2048:
        num_warps = 8
    elif block_r >= 512:
        num_warps = 4
    elif block_r >= 128:
        num_warps = 2

    _gelu_std_kernel[(out_numel,)](
        input,
        out,
        NDIM=ndim,
        SHAPE=shape,
        IN_STRIDES=in_strides,
        OUT_STRIDES=out_strides,
        REDUCE_FLAGS=reduce_flags,
        OUT_MAP=out_map,
        R=int(r),
        CORRECTION=correction,
        APPROXIMATE=approximate,
        BLOCK_R=block_r,
        num_warps=num_warps,
    )

    return out

import triton
import triton.language as tl


_MAX_NDIM = 8
_SINGLE_KERNEL_MAX_BLOCK = 65536
_CHUNK_BLOCK = 1024


@triton.jit
def _zero_kernel(Y, TOTAL: tl.constexpr, BLOCK: tl.constexpr):
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    tl.store(Y + offs, tl.zeros((BLOCK,), tl.float32), mask=offs < TOTAL)


@triton.jit
def _sum_store_kernel(
    X,
    Y,
    REDUCE_SIZE: tl.constexpr,
    BLOCK_R: tl.constexpr,
    NDIM: tl.constexpr,
    ACC_FLOAT: tl.constexpr,
    S0: tl.constexpr,
    S1: tl.constexpr,
    S2: tl.constexpr,
    S3: tl.constexpr,
    S4: tl.constexpr,
    S5: tl.constexpr,
    S6: tl.constexpr,
    S7: tl.constexpr,
    T0: tl.constexpr,
    T1: tl.constexpr,
    T2: tl.constexpr,
    T3: tl.constexpr,
    T4: tl.constexpr,
    T5: tl.constexpr,
    T6: tl.constexpr,
    T7: tl.constexpr,
    R0: tl.constexpr,
    R1: tl.constexpr,
    R2: tl.constexpr,
    R3: tl.constexpr,
    R4: tl.constexpr,
    R5: tl.constexpr,
    R6: tl.constexpr,
    R7: tl.constexpr,
):
    out_pid = tl.program_id(0)

    tmp = out_pid
    base = tl.full((), 0, tl.int64)

    if NDIM >= 8:
        if not R7:
            i7 = tmp % S7
            tmp = tmp // S7
            base += i7 * T7
    if NDIM >= 7:
        if not R6:
            i6 = tmp % S6
            tmp = tmp // S6
            base += i6 * T6
    if NDIM >= 6:
        if not R5:
            i5 = tmp % S5
            tmp = tmp // S5
            base += i5 * T5
    if NDIM >= 5:
        if not R4:
            i4 = tmp % S4
            tmp = tmp // S4
            base += i4 * T4
    if NDIM >= 4:
        if not R3:
            i3 = tmp % S3
            tmp = tmp // S3
            base += i3 * T3
    if NDIM >= 3:
        if not R2:
            i2 = tmp % S2
            tmp = tmp // S2
            base += i2 * T2
    if NDIM >= 2:
        if not R1:
            i1 = tmp % S1
            tmp = tmp // S1
            base += i1 * T1
    if NDIM >= 1:
        if not R0:
            i0 = tmp % S0
            base += i0 * T0

    r = tl.arange(0, BLOCK_R)
    rtmp = r
    roff = tl.zeros((BLOCK_R,), tl.int64)

    if NDIM >= 8:
        if R7:
            j7 = rtmp % S7
            rtmp = rtmp // S7
            roff += j7 * T7
    if NDIM >= 7:
        if R6:
            j6 = rtmp % S6
            rtmp = rtmp // S6
            roff += j6 * T6
    if NDIM >= 6:
        if R5:
            j5 = rtmp % S5
            rtmp = rtmp // S5
            roff += j5 * T5
    if NDIM >= 5:
        if R4:
            j4 = rtmp % S4
            rtmp = rtmp // S4
            roff += j4 * T4
    if NDIM >= 4:
        if R3:
            j3 = rtmp % S3
            rtmp = rtmp // S3
            roff += j3 * T3
    if NDIM >= 3:
        if R2:
            j2 = rtmp % S2
            rtmp = rtmp // S2
            roff += j2 * T2
    if NDIM >= 2:
        if R1:
            j1 = rtmp % S1
            rtmp = rtmp // S1
            roff += j1 * T1
    if NDIM >= 1:
        if R0:
            j0 = rtmp % S0
            roff += j0 * T0

    vals = tl.load(X + base + roff, mask=r < REDUCE_SIZE, other=0.0)
    if ACC_FLOAT:
        vals = vals.to(tl.float32)
    res = tl.sum(vals, axis=0)
    tl.store(Y + out_pid, res)


