def _prod(seq):
    v = 1
    for x in seq:
        v *= int(x)
    return v


def _next_power_of_2(x):
    x = int(x)
    p = 1
    while p < x:
        p <<= 1
    return p


def _get_strides(x):
    s = getattr(x, "stride", None)
    if callable(s):
        return tuple(int(v) for v in s())
    s = getattr(x, "strides", None)
    if s is not None:
        return tuple(int(v) for v in s)
    raise AttributeError("input tensor must expose strides")


def _normalize_dims(dim, ndim):
    if dim is None:
        return tuple(range(ndim))

    if isinstance(dim, (tuple, list)):
        raw = list(dim)
    else:
        raw = [dim]

    out = []
    for d in raw:
        d = int(d)
        if d < 0:
            d += ndim
        if d < 0 or d >= ndim:
            raise IndexError("dimension out of range")
        if d in out:
            raise ValueError("duplicate value in dim")
        out.append(d)
    return tuple(out)


def _dtype_name(x):
    try:
        return str(x).lower()
    except Exception:
        return ""


def sum(input, dim, keepdim=False, *, dtype=None):
    shape = tuple(int(v) for v in input.shape)
    ndim = len(shape)

    if ndim > _MAX_NDIM:
        raise ValueError("this Triton implementation supports tensors with at most 8 dimensions")

    strides = _get_strides(input)
    dims = _normalize_dims(dim, ndim)
    reduce_flags = [False] * _MAX_NDIM
    for d in dims:
        reduce_flags[d] = True

    out_shape = []
    if keepdim:
        for i in range(ndim):
            if reduce_flags[i]:
                out_shape.append(1)
            else:
                out_shape.append(shape[i])
    else:
        for i in range(ndim):
            if not reduce_flags[i]:
                out_shape.append(shape[i])

    if dtype is None:
        output = input.new_empty(tuple(out_shape))
    else:
        output = input.new_empty(tuple(out_shape), dtype=dtype)

    total_out = _prod(out_shape)
    if total_out == 0:
        return output

    reduce_size = 1
    for d in dims:
        reduce_size *= shape[d]

    kernel_shape = []
    for i in range(_MAX_NDIM):
        if i < ndim:
            v = shape[i]
            if v == 0:
                v = 1
            kernel_shape.append(int(v))
        else:
            kernel_shape.append(1)

    kernel_strides = []
    for i in range(_MAX_NDIM):
        if i < ndim:
            kernel_strides.append(int(strides[i]))
        else:
            kernel_strides.append(0)

    source_dtype = _dtype_name(getattr(input, "dtype", ""))
    target_dtype = _dtype_name(dtype) if dtype is not None else source_dtype
    acc_float = (
        "float16" in source_dtype
        or "bfloat16" in source_dtype
        or "float32" in target_dtype
        or ("float" in target_dtype and "64" not in target_dtype)
    )

    common = dict(
        NDIM=ndim,
        ACC_FLOAT=acc_float,
        S0=kernel_shape[0],
        S1=kernel_shape[1],
        S2=kernel_shape[2],
        S3=kernel_shape[3],
        S4=kernel_shape[4],
        S5=kernel_shape[5],
        S6=kernel_shape[6],
        S7=kernel_shape[7],
        T0=kernel_strides[0],
        T1=kernel_strides[1],
        T2=kernel_strides[2],
        T3=kernel_strides[3],
        T4=kernel_strides[4],
        T5=kernel_strides[5],
        T6=kernel_strides[6],
        T7=kernel_strides[7],
        R0=reduce_flags[0],
        R1=reduce_flags[1],
        R2=reduce_flags[2],
        R3=reduce_flags[3],
        R4=reduce_flags[4],
        R5=reduce_flags[5],
        R6=reduce_flags[6],
        R7=reduce_flags[7],
    )

    if reduce_size <= _SINGLE_KERNEL_MAX_BLOCK:
        block_r = _next_power_of_2(reduce_size if reduce_size > 0 else 1)
        if block_r >= 2048:
            warps = 8
        elif block_r >= 256:
            warps = 4
        else:
            warps = 1

        _sum_store_kernel[(total_out,)](
            input,
            output,
            REDUCE_SIZE=reduce_size,
            BLOCK_R=block_r,
            num_warps=warps,
            **common,
        )
    else:
        zero_block = 256
        _zero_kernel[(triton.cdiv(total_out, zero_block),)](
            output,
            TOTAL=total_out,
            BLOCK=zero_block,
            num_warps=4,
        )

        chunks = triton.cdiv(reduce_size, _CHUNK_BLOCK)
        _sum_atomic_kernel[(total_out, chunks)](
            input,
            output,
            REDUCE_SIZE=reduce_size,
            BLOCK_R=_CHUNK_BLOCK,
            num_warps=4,
            **common,
        )

    return output

import time
import itertools
import operator
import triton
import triton.language as tl


_seed_counter = itertools.count(1)


@triton.jit
def _rand_uniform_kernel(out, n: tl.constexpr, seed, BLOCK_SIZE: tl.constexpr):
    pid = tl.program_id(0)
    offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n
    values = tl.rand(seed, offsets)
    tl.store(out + offsets, values, mask=mask)


def _get_cupy():
    import cupy as cp
    return cp


def _canonical_shape(size):
    if len(size) == 0:
        return ()
    if len(size) == 1:
        item = size[0]
        if isinstance(item, (list, tuple)):
            seq = item
        elif not isinstance(item, (str, bytes)) and hasattr(item, "__iter__"):
            try:
                seq = tuple(item)
            except TypeError:
                seq = size
        else:
            seq = size
    else:
        seq = size

    shape = []
    for dim in seq:
        dim = operator.index(dim)
        if dim < 0:
            raise ValueError("negative dimensions are not allowed")
        shape.append(dim)
    return tuple(shape)


def _numel(shape):
    n = 1
    for dim in shape:
        n *= dim
    return int(n)


def _shape_of(x):
    shape = getattr(x, "shape", None)
    if shape is None:
        return None
    return tuple(int(d) for d in shape)


def _numel_of(x):
    size = getattr(x, "size", None)
    if isinstance(size, int):
        return int(size)
    if callable(size):
        try:
            return int(size())
        except TypeError:
            pass

    numel = getattr(x, "numel", None)
    if callable(numel):
        return int(numel())

    shape = _shape_of(x)
    if shape is not None:
        return _numel(shape)

    raise TypeError("could not determine output size")


def _is_c_contiguous(x):
    flags = getattr(x, "flags", None)
    if flags is None:
        return True

    for name in ("c_contiguous", "C_CONTIGUOUS"):
        try:
            value = getattr(flags, name)
            return bool(value)
        except Exception:
            pass

    try:
        return bool(flags["C_CONTIGUOUS"])
    except Exception:
        return True


def _normalize_dtype(dtype):
    cp = _get_cupy()

    if dtype is None:
        return cp.float32

    if dtype is float:
        return cp.float32

    s = str(dtype).lower().replace(" ", "")

    if s.endswith("float16") or s.endswith("half") or s == "fp16":
        return cp.float16
    if s.endswith("float32") or s.endswith("single") or s == "float" or s == "fp32":
        return cp.float32
    if s.endswith("float64") or s.endswith("double") or s == "fp64":
        return cp.float64
    if s.endswith("complex64") or s == "cfloat":
        return cp.complex64
    if s.endswith("complex128") or s == "cdouble":
        return cp.complex128

    try:
        dt = cp.dtype(dtype)
    except Exception as exc:
        raise TypeError("unsupported dtype") from exc

    if dt.kind not in ("f", "c"):
        raise TypeError("rand only supports floating point and complex dtypes")

    return dt


def _dtype_kind(x):
    dtype = getattr(x, "dtype", None)
    if dtype is None:
        return None
    kind = getattr(dtype, "kind", None)
    if kind is not None:
        return kind
    s = str(dtype).lower()
    if "complex" in s:
        return "c"
    if "float" in s or "half" in s or "double" in s:
        return "f"
    return None


def _real_dtype_for_complex(dtype):
    cp = _get_cupy()
    dt = cp.dtype(dtype)
    if dt == cp.dtype(cp.complex64):
        return cp.float32
    if dt == cp.dtype(cp.complex128):
        return cp.float64
    raise TypeError("unsupported complex dtype")


def _flat_fill_target(out, n):
    kind = _dtype_kind(out)

    if kind is not None and kind not in ("f", "c"):
        raise TypeError("rand only supports floating point and complex outputs")

    if not _is_c_contiguous(out) and n > 1:
        raise ValueError("out must be contiguous")

    if kind == "c":
        real_dtype = _real_dtype_for_complex(getattr(out, "dtype"))
        return out.view(real_dtype).reshape((2 * n,)), 2 * n

    reshape = getattr(out, "reshape", None)
    if callable(reshape):
        try:
            return reshape((n,)), n
        except Exception:
            pass

    return out, n


def _device_index(device):
    if device is None:
        return None

    if isinstance(device, int):
        if device < 0:
            raise ValueError("device index must be non-negative")
        return device

    s = str(device).lower().replace(" ", "")

    if s == "cpu" or s.startswith("cpu:"):
        raise NotImplementedError("CPU output is not supported by this Triton implementation")

    if "cuda" not in s and "gpu" not in s:
        raise ValueError("only CUDA devices are supported")

    if ":" in s:
        tail = s.rsplit(":", 1)[1]
        if tail:
            return int(tail)

    return None


def _seed_from_generator(generator):
    if generator is None:
        return (time.time_ns() ^ (next(_seed_counter) * 0x9E3779B97F4A7C15)) & 0x7FFFFFFF

    if isinstance(generator, int):
        return generator & 0x7FFFFFFF

    for name in ("integers", "randint"):
        fn = getattr(generator, name, None)
        if callable(fn):
            try:
                return int(fn(0, 0x7FFFFFFF)) & 0x7FFFFFFF
            except Exception:
                pass

    for name in ("initial_seed", "seed"):
        fn = getattr(generator, name, None)
        if callable(fn):
            try:
                return int(fn()) & 0x7FFFFFFF
            except Exception:
                pass

    try:
        return int(generator) & 0x7FFFFFFF
    except Exception as exc:
        raise TypeError("unsupported generator") from exc


def _validate_layout(layout):
    if layout is None:
        return
    s = str(layout).lower()
    if not s.endswith("strided") and s != "strided":
        raise NotImplementedError("only strided layout is supported")


def rand(*size, generator=None, out=None, dtype=None, layout=None, device=None, requires_grad=False, pin_memory=False):
    if requires_grad:
        raise NotImplementedError("requires_grad is not supported by this Triton-only implementation")
    if pin_memory:
        raise NotImplementedError("pin_memory is only meaningful for CPU allocation")
    _validate_layout(layout)

    if out is not None and len(size) == 0:
        shape = _shape_of(out)
        if shape is None:
            n = _numel_of(out)
            shape = (n,)
    else:
        shape = _canonical_shape(size)
        n = _numel(shape)

    if out is None:
        cp = _get_cupy()
        dt = _normalize_dtype(dtype)
        if cp.dtype(dt).kind not in ("f", "c"):
            raise TypeError("rand only supports floating point and complex dtypes")

        dev_id = _device_index(device)
        if dev_id is None:
            out = cp.empty(shape, dtype=dt)
        else:
            with cp.cuda.Device(dev_id):
                out = cp.empty(shape, dtype=dt)
    else:
        out_shape = _shape_of(out)
        if out_shape is not None and out_shape != tuple(shape):
            raise ValueError("out shape does not match requested size")
        n = _numel_of(out)

    target, fill_n = _flat_fill_target(out, n)

    if fill_n == 0:
        return out

    seed = _seed_from_generator(generator)
    block_size = 1024
    grid = (triton.cdiv(fill_n, block_size),)
    _rand_uniform_kernel[grid](target, fill_n, seed, BLOCK_SIZE=block_size)

    return out


__all__ = ["rand"]

import triton
import triton.language as tl


_MAX_DIMS = 16


@triton.jit
def _mul_sub_flat_kernel(
    input_ptr,
    mul_ptr,
    sub_ptr,
    out_ptr,
    n,
    mul_scalar,
    sub_scalar,
    alpha,
    HAS_MUL_TENSOR: tl.constexpr,
    HAS_SUB_TENSOR: tl.constexpr,
    MUL_SINGLE: tl.constexpr,
    SUB_SINGLE: tl.constexpr,
    BLOCK_SIZE: tl.constexpr,
):
    offsets = tl.program_id(0) * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n

    x = tl.load(input_ptr + offsets, mask=mask, other=0.0)

    if HAS_MUL_TENSOR:
        if MUL_SINGLE:
            m = tl.load(mul_ptr + 0)
        else:
            m = tl.load(mul_ptr + offsets, mask=mask, other=0.0)
    else:
        m = mul_scalar

    if HAS_SUB_TENSOR:
        if SUB_SINGLE:
            s = tl.load(sub_ptr + 0)
        else:
            s = tl.load(sub_ptr + offsets, mask=mask, other=0.0)
    else:
        s = sub_scalar

    y = x * m - alpha * s
    tl.store(out_ptr + offsets, y, mask=mask)


@triton.jit
def _mul_sub_broadcast_kernel(
    input_ptr,
    mul_ptr,
    sub_ptr,
    out_ptr,
    total,
    mul_scalar,
    sub_scalar,
    alpha,
    OUT_SHAPE: tl.constexpr,
    IN_STRIDES: tl.constexpr,
    MUL_STRIDES: tl.constexpr,
    SUB_STRIDES: tl.constexpr,
    OUT_STRIDES: tl.constexpr,
    NDIM: tl.constexpr,
    HAS_MUL_TENSOR: tl.constexpr,
    HAS_SUB_TENSOR: tl.constexpr,
    BLOCK_SIZE: tl.constexpr,
    MAX_DIMS: tl.constexpr,
):
    linear = tl.program_id(0) * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = linear < total

    rem = linear
    in_off = tl.zeros((BLOCK_SIZE,), dtype=tl.int64)
    mul_off = tl.zeros((BLOCK_SIZE,), dtype=tl.int64)
    sub_off = tl.zeros((BLOCK_SIZE,), dtype=tl.int64)
    out_off = tl.zeros((BLOCK_SIZE,), dtype=tl.int64)

    for k in tl.static_range(0, MAX_DIMS):
        d = MAX_DIMS - 1 - k
        if d < NDIM:
            size = OUT_SHAPE[d]
            coord = rem % size
            rem = rem // size
            in_off += coord * IN_STRIDES[d]
            mul_off += coord * MUL_STRIDES[d]
            sub_off += coord * SUB_STRIDES[d]
            out_off += coord * OUT_STRIDES[d]

    x = tl.load(input_ptr + in_off, mask=mask, other=0.0)

    if HAS_MUL_TENSOR:
        m = tl.load(mul_ptr + mul_off, mask=mask, other=0.0)
    else:
        m = mul_scalar

    if HAS_SUB_TENSOR:
        s = tl.load(sub_ptr + sub_off, mask=mask, other=0.0)
    else:
        s = sub_scalar

    y = x * m - alpha * s
    tl.store(out_ptr + out_off, y, mask=mask)


def _is_tensor(x):
    return hasattr(x, "shape") and hasattr(x, "stride") and hasattr(x, "numel")


def _shape(x):
    return tuple(int(v) for v in x.shape)


def _stride(x):
    s = x.stride()
    return tuple(int(v) for v in s)


def _numel(x):
    n = x.numel
    if callable(n):
        n = n()
    return int(n)


def _prod(shape):
    p = 1
    for v in shape:
        p *= int(v)
    return int(p)


def _broadcast_dim(dims):
    non_one = [int(d) for d in dims if int(d) != 1]
    if not non_one:
        return 1
    if 0 in non_one:
        for d in non_one:
            if d != 0:
                raise ValueError("operands could not be broadcast together")
        return 0
    first = non_one[0]
    for d in non_one[1:]:
        if d != first:
            raise ValueError("operands could not be broadcast together")
    return first


def _broadcast_shape(*shapes):
    max_ndim = 0
    for s in shapes:
        if len(s) > max_ndim:
            max_ndim = len(s)

    result = []
    for i in range(max_ndim):
        dims = []
        for s in shapes:
            j = len(s) - max_ndim + i
            dims.append(s[j] if j >= 0 else 1)
        result.append(_broadcast_dim(dims))
    return tuple(result)


def _pad_tuple(values, length, fill=0):
    values = tuple(int(v) for v in values)
    if len(values) > length:
        raise ValueError("too many dimensions for this Triton implementation")
    return values + tuple(int(fill) for _ in range(length - len(values)))


def _broadcast_strides(tensor_shape, tensor_strides, out_shape):
    out_ndim = len(out_shape)
    in_ndim = len(tensor_shape)
    leading = out_ndim - in_ndim
    result = []

    for i in range(out_ndim):
        src_i = i - leading
        if src_i < 0:
            result.append(0)
        else:
            dim = int(tensor_shape[src_i])
            stride = int(tensor_strides[src_i])
            if dim == 1 and int(out_shape[i]) != 1:
                result.append(0)
            else:
                result.append(stride)

    return tuple(result)


def _is_contiguous(x):
    try:
        return bool(x.is_contiguous())
    except Exception:
        return False


def _can_use_flat(input, other_mul, other_sub, out, out_shape, mul_is_tensor, sub_is_tensor):
    if _shape(input) != out_shape:
        return False
    if not _is_contiguous(input) or not _is_contiguous(out):
        return False

    if mul_is_tensor:
        if _numel(other_mul) != 1:
            if _shape(other_mul) != out_shape or not _is_contiguous(other_mul):
                return False

    if sub_is_tensor:
        if _numel(other_sub) != 1:
            if _shape(other_sub) != out_shape or not _is_contiguous(other_sub):
                return False

    return True


def mul_sub(input, other_mul, other_sub, alpha=1, out=None):
    mul_is_tensor = _is_tensor(other_mul)
    sub_is_tensor = _is_tensor(other_sub)

    shapes = [_shape(input)]
    if mul_is_tensor:
        shapes.append(_shape(other_mul))
    if sub_is_tensor:
        shapes.append(_shape(other_sub))

    out_shape = _broadcast_shape(*shapes)

    if out is None:
        out = input.new_empty(out_shape)
    else:
        if _shape(out) != out_shape:
            raise ValueError("out has incorrect shape")

    total = _prod(out_shape)
    if total == 0:
        return out

    block_size = 1024
    grid = (triton.cdiv(total, block_size),)

    mul_ptr = other_mul if mul_is_tensor else input
    sub_ptr = other_sub if sub_is_tensor else input
    mul_scalar = 0 if mul_is_tensor else other_mul
    sub_scalar = 0 if sub_is_tensor else other_sub

    if _can_use_flat(input, other_mul, other_sub, out, out_shape, mul_is_tensor, sub_is_tensor):
        _mul_sub_flat_kernel[grid](
            input,
            mul_ptr,
            sub_ptr,
            out,
            total,
            mul_scalar,
            sub_scalar,
            alpha,
            HAS_MUL_TENSOR=mul_is_tensor,
            HAS_SUB_TENSOR=sub_is_tensor,
            MUL_SINGLE=(mul_is_tensor and _numel(other_mul) == 1),
            SUB_SINGLE=(sub_is_tensor and _numel(other_sub) == 1),
            BLOCK_SIZE=block_size,
            num_warps=4,
        )
        return out

    ndim = len(out_shape)
    if ndim > _MAX_DIMS:
        raise ValueError("too many dimensions for this Triton implementation")

    out_shape_padded = _pad_tuple(out_shape, _MAX_DIMS, 1)

    in_strides = _broadcast_strides(_shape(input), _stride(input), out_shape)

    if mul_is_tensor:
        mul_strides = _broadcast_strides(_shape(other_mul), _stride(other_mul), out_shape)
    else:
        mul_strides = tuple(0 for _ in range(ndim))

    if sub_is_tensor:
        sub_strides = _broadcast_strides(_shape(other_sub), _stride(other_sub), out_shape)
    else:
        sub_strides = tuple(0 for _ in range(ndim))

    out_strides = _stride(out)

    _mul_sub_broadcast_kernel[grid](
        input,
        mul_ptr,
        sub_ptr,
        out,
        total,
        mul_scalar,
        sub_scalar,
        alpha,
        OUT_SHAPE=out_shape_padded,
        IN_STRIDES=_pad_tuple(in_strides, _MAX_DIMS, 0),
        MUL_STRIDES=_pad_tuple(mul_strides, _MAX_DIMS, 0),
        SUB_STRIDES=_pad_tuple(sub_strides, _MAX_DIMS, 0),
        OUT_STRIDES=_pad_tuple(out_strides, _MAX_DIMS, 0),
        NDIM=ndim,
        HAS_MUL_TENSOR=mul_is_tensor,
        HAS_SUB_TENSOR=sub_is_tensor,
        BLOCK_SIZE=block_size,
        MAX_DIMS=_MAX_DIMS,
        num_warps=4,
    )

    return out

import triton
import triton.language as tl


@triton.jit
def _mul_tensor_tensor_kernel(
    a, b, c, n,
    s0, s1, s2, s3, s4, s5, s6, s7,
    d0, d1, d2, d3, d4, d5, d6, d7,
    as0, as1, as2, as3, as4, as5, as6, as7,
    bs0, bs1, bs2, bs3, bs4, bs5, bs6, bs7,
    cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7,
    BLOCK: tl.constexpr,
):
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n
    idx = offs

    ao = ((idx // d0) % s0) * as0 + ((idx // d1) % s1) * as1 + ((idx // d2) % s2) * as2 + ((idx // d3) % s3) * as3 + ((idx // d4) % s4) * as4 + ((idx // d5) % s5) * as5 + ((idx // d6) % s6) * as6 + ((idx // d7) % s7) * as7
    bo = ((idx // d0) % s0) * bs0 + ((idx // d1) % s1) * bs1 + ((idx // d2) % s2) * bs2 + ((idx // d3) % s3) * bs3 + ((idx // d4) % s4) * bs4 + ((idx // d5) % s5) * bs5 + ((idx // d6) % s6) * bs6 + ((idx // d7) % s7) * bs7
    co = ((idx // d0) % s0) * cs0 + ((idx // d1) % s1) * cs1 + ((idx // d2) % s2) * cs2 + ((idx // d3) % s3) * cs3 + ((idx // d4) % s4) * cs4 + ((idx // d5) % s5) * cs5 + ((idx // d6) % s6) * cs6 + ((idx // d7) % s7) * cs7

    av = tl.load(a + ao, mask=mask, other=0.0)
    bv = tl.load(b + bo, mask=mask, other=0.0)
    tl.store(c + co, av * bv, mask=mask)


