    as0, as1, as2, as3, as4, as5, as6, as7,
    bs0, bs1, bs2, bs3, bs4, bs5, bs6, bs7,
    cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7,
    A_COMPLEX: tl.constexpr,
    B_COMPLEX: tl.constexpr,
    A_BITS: tl.constexpr,
    B_BITS: tl.constexpr,
    OUT_BITS: tl.constexpr,
    BLOCK: tl.constexpr,
):
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n
    idx = offs

    ao = ((idx // d0) % s0) * as0 + ((idx // d1) % s1) * as1 + ((idx // d2) % s2) * as2 + ((idx // d3) % s3) * as3 + ((idx // d4) % s4) * as4 + ((idx // d5) % s5) * as5 + ((idx // d6) % s6) * as6 + ((idx // d7) % s7) * as7
    bo = ((idx // d0) % s0) * bs0 + ((idx // d1) % s1) * bs1 + ((idx // d2) % s2) * bs2 + ((idx // d3) % s3) * bs3 + ((idx // d4) % s4) * bs4 + ((idx // d5) % s5) * bs5 + ((idx // d6) % s6) * bs6 + ((idx // d7) % s7) * bs7
    co = ((idx // d0) % s0) * cs0 + ((idx // d1) % s1) * cs1 + ((idx // d2) % s2) * cs2 + ((idx // d3) % s3) * cs3 + ((idx // d4) % s4) * cs4 + ((idx // d5) % s5) * cs5 + ((idx // d6) % s6) * cs6 + ((idx // d7) % s7) * cs7

    if A_COMPLEX:
        if A_BITS == 128:
            af = a.to(tl.pointer_type(tl.float64))
            ar = tl.load(af + ao * 2, mask=mask, other=0.0)
            ai = tl.load(af + ao * 2 + 1, mask=mask, other=0.0)
        else:
            af = a.to(tl.pointer_type(tl.float32))
            ar = tl.load(af + ao * 2, mask=mask, other=0.0)
            ai = tl.load(af + ao * 2 + 1, mask=mask, other=0.0)
    else:
        ar = tl.load(a + ao, mask=mask, other=0.0)
        if OUT_BITS == 128:
            ai = tl.zeros((BLOCK,), dtype=tl.float64)
        else:
            ai = tl.zeros((BLOCK,), dtype=tl.float32)

    if B_COMPLEX:
        if B_BITS == 128:
            bf = b.to(tl.pointer_type(tl.float64))
            br = tl.load(bf + bo * 2, mask=mask, other=0.0)
            bi = tl.load(bf + bo * 2 + 1, mask=mask, other=0.0)
        else:
            bf = b.to(tl.pointer_type(tl.float32))
            br = tl.load(bf + bo * 2, mask=mask, other=0.0)
            bi = tl.load(bf + bo * 2 + 1, mask=mask, other=0.0)
    else:
        br = tl.load(b + bo, mask=mask, other=0.0)
        if OUT_BITS == 128:
            bi = tl.zeros((BLOCK,), dtype=tl.float64)
        else:
            bi = tl.zeros((BLOCK,), dtype=tl.float32)

    if OUT_BITS == 128:
        ar = ar.to(tl.float64)
        ai = ai.to(tl.float64)
        br = br.to(tl.float64)
        bi = bi.to(tl.float64)
        cf = c.to(tl.pointer_type(tl.float64))
    else:
        ar = ar.to(tl.float32)
        ai = ai.to(tl.float32)
        br = br.to(tl.float32)
        bi = bi.to(tl.float32)
        cf = c.to(tl.pointer_type(tl.float32))

    rr = ar * br - ai * bi
    ri = ar * bi + ai * br
    tl.store(cf + co * 2, rr, mask=mask)
    tl.store(cf + co * 2 + 1, ri, mask=mask)


